import {FACTIONS,COUNCILS,CLANS,MAP_PRESET,INITIAL_ARMIES,TACTICS,FACTION_TACTICS,buildExtraClans,WORLD_TENSION_EVENTS,FACTION_START,FACTION_CAMPAIGNS,INITIAL_RELATIONS,DIPLOMACY_STATUS,getRelation,setRelation} from './data.js';
