const state={year:551,turn:1,month:1,started:false,narrativeReady:false,lobbyFaction:'SILLA',lobbyClanId:FACTION_CAMPAIGNS.SILLA.royalClan,playerFaction:'SILLA',activeClanId:'kim_royal',selectedTileKey:'2,2',tileCardOpen:false,royalAuth:55,nationalFood:1200,nationalGold:500,northWarApproved:false,coupMandate:false,goguryeoStance:null,goguryeoQuestChoice:null,revoltPending:false,selectedArmyId:null,movingArmyId:null,armySeq:6,clans:structuredClone(CLANS),tiles:Object.fromEntries(MAP_PRESET.map(t=>[tileKey(t.q,t.r),structuredClone(t)])),armies:structuredClone(INITIAL_ARMIES),pendingBattles:[],battleCancelRequested:false,selectedNobleId:null,hanseongTrigger:false,allianceBroken:false,goguryeoHanseongLost:false,goguryeoTilesLost:0,trust:60,legitimacy:70,isabuRelation:50,relations:structuredClone(INITIAL_RELATIONS),pendingWarPlan:null,aiResources:{GOGURYEO:{gold:420,food:900},BAEKJE:{gold:420,food:900},SILLA:{gold:420,food:900}},aiStances:{},flags:{treatyClarity:null,sillaRaidScope:null,baekjeResponse:null,gwansanOutcome:null,goguryeoPact:false,gayaFavorBaekje:0,gayaFavorSilla:0},triggers:{sq01Turn:null,sq02:false,sq03:false,sq04:false,sq05:false,hanseongBattleTurn:null},eventQueue:[],eventOpen:false,quests:{mainIndex:0,completed:new Set(),sideCompleted:new Set(),path:[],cutscenes:new Set(),sq01Survives:null,sq05Survives:null,ending:null,dialogues:{},history:[],scenePage:0}};
Object.assign(state.clans,buildExtraClans());
for(const clan of Object.values(state.clans)){clan.manorLevel??=0;clan.leverage??=0;clan.loyaltyDecayTurns??=0;clan.purgesCount??=0}
Object.assign(state,{warJustification:25,worldTension:35,warAgendaApproved:false,promisedLandClanId:null,marriageContracts:new Set(),taxReliefTurns:0,clanTaxShare:0,politicalAllies:new Set(),worldEventTurn:0,lastWorldBriefing:'북방 돌궐의 움직임과 한강 유역의 교역 갈등이 커지고 있습니다.',tileOwnershipSnapshot:Object.fromEntries(Object.entries(state.tiles).map(([key,tile])=>[key,tile.owner]))});
