function addLog(message){const entry=document.createElement('div');entry.className='log-entry';entry.textContent=message;$('log-box').prepend(entry)}
function playerArmies(){return state.armies.filter(a=>a.owner===state.playerFaction)}
function royalArmyStrength(){return state.armies.filter(a=>a.owner===state.playerFaction&&a.clanId===playerClans().find(c=>c.isKing)?.id).reduce((n,a)=>n+a.troops,0)}
function hasCoupConditions(){const clan=activeClan(),king=playerClans().find(c=>c.isKing);return Boolean(clan&&!clan.isKing&&king&&state.coupMandate&&(state.royalAuth<=40||clan.privateArmy>royalArmyStrength()))}
function mainQuests(){return state.playerFaction==='GOGURYEO'?GOGURYEO_QUESTS:NARRATIVE.quests}
function playerClans(){return Object.values(state.clans).filter(c=>c.faction===state.playerFaction)}
function activeClan(){return state.clans[state.activeClanId]}
function displaySpeaker(name,sceneId=''){if(/백제.*사신/.test(name))return "백제 상좌평 · 사비 사절 '사법명'";if(/신라.*사신/.test(name))return "신라 대아찬 · 금성 사절 '거칠부'";if(/매복.*지휘관|지휘관.*매복/.test(name))return "신라 삼년산성 군주 · 장군 '고간(도도)'";return name}
function displayEmotion(tag){const labels={neutral:'😐 담담한 어조',bitter:'😠 쓰라림을 삼키며 날 선 목소리로',sad:'😔 침통한 기색',angry:'😠 분노를 억누르지 못하고',shout:'🔥 격앙된 외침',resigned:'😮‍💨 체념한 듯 낮게',whisper:'🤫 숨죽여 속삭이며',worried:'😟 불안을 감추지 못하고',excited:'✨ 들뜬 기색',surprised:'😮 놀라 숨을 삼키며',grateful:'🙏 고마움을 담아'};return String(tag).replace(/[\[\]]/g,'').split(/[→>]/).map(part=>labels[part.trim().toLowerCase()]||'😐 담담한 어조').join(' → ')}
function councilName(){return COUNCILS[state.playerFaction]||'귀족 회의'}

const FLAG_LABELS=[['한강 맹약 문서화','treatyClarity'],['나제동맹 기습 수위','sillaRaidScope'],['백제의 대응','baekjeResponse'],['관산성 결전의 결말','gwansanOutcome'],['고구려 밀약 첩보','goguryeoPact'],['대가야의 백제 호감','gayaFavorBaekje'],['대가야의 신라 호감','gayaFavorSilla']];
function syncNarrativeFlags(){NARRATIVE.flags.treatyClarity=state.flags.treatyClarity;NARRATIVE.flags.sillaRaidScope=state.flags.sillaRaidScope;NARRATIVE.flags.baekjeResponse=state.flags.baekjeResponse;NARRATIVE.flags.gwansanOutcome=state.flags.gwansanOutcome;NARRATIVE.flags.goguryeoPact=state.flags.goguryeoPact;NARRATIVE.flags.gayaFavorBaekje=state.flags.gayaFavorBaekje;NARRATIVE.flags.gayaFavorSilla=state.flags.gayaFavorSilla}
function showCutscene(id){if(state.quests.cutscenes.has(id)||state.quests.pendingScene===id)return;enqueueStoryEvent('cutscene',id)}
function enqueueStoryEvent(type,id){const exists=state.eventQueue.some(event=>event.type===type&&event.id===id);if(!exists)state.eventQueue.push({type,id});pumpStoryQueue()}
function pumpStoryQueue(){if(!state.started||state.eventOpen||!state.eventQueue.length||$('ending-modal').open||[...document.querySelectorAll('dialog[open]')].some(dialog=>dialog.id!=='campaign-lobby'))return;const event=state.eventQueue.shift();state.eventOpen=true;if(event.type==='annex')renderAnnexationEvent(event.id);else if(event.type==='cutscene')renderCutscene(event.id);else if(event.type==='revolt')renderRevoltEvent(event.id);else renderSideQuestEvent(event.id)}
function setupCutscenePages(id,showChoices=true){const context=$('cutscene-context'),lines=$('cutscene-lines'),choices=$('cutscene-choices'),next=$('btn-cutscene-continue'),skip=$('btn-cutscene-skip'),indicator=$('cutscene-page-indicator');state.quests.scenePage=1;context.textContent=CUTSCENE_CONTEXT[id]||CUTSCENE_CONTEXT[id==='CS-04-SILLA'?'CS-04-SILLA':'CS-01'];context.hidden=false;lines.hidden=true;choices.hidden=true;indicator.textContent='1 / 3';indicator.hidden=false;next.textContent=UI_LABELS.chapterNext;next.style.display='inline-block';skip.textContent=UI_LABELS.chapterSkip;skip.style.display='inline-block';next.onclick=()=>{if(state.quests.scenePage===1){state.quests.scenePage=2;context.hidden=true;lines.hidden=false;indicator.textContent='2 / 3'}else{state.quests.scenePage=3;lines.hidden=false;choices.hidden=!showChoices;indicator.textContent='3 / 3';next.style.display='none';skip.style.display='none';if(!showChoices){next.style.display='inline-block';next.onclick=closeCutscene}}};skip.onclick=()=>{state.quests.scenePage=3;context.hidden=true;lines.hidden=false;choices.hidden=!showChoices;indicator.textContent='3 / 3';next.style.display='none';skip.style.display='none';if(!showChoices){next.style.display='inline-block';next.onclick=closeCutscene}}}function chronicle(questId,choice,result){state.quests.history??=[];state.quests.history.push({questId,choice,result,turn:state.turn})}function cutsceneTip(id,letter,label){if(id==='CS-02-S')return letter==='A'?UI_LABELS.tooltipCutscenePartial:letter==='B'?UI_LABELS.tooltipCutsceneFull:UI_LABELS.tooltipCutsceneDelegate;if(id==='CS-02-B')return letter==='A'?UI_LABELS.tooltipCutsceneIgnore:letter==='B'?UI_LABELS.tooltipCutscenePreempt:UI_LABELS.tooltipCutsceneDelegate;if(id==='CS-04')return letter==='A'?UI_LABELS.tooltipCutsceneAttend:UI_LABELS.tooltipCutsceneAbsent;if(id==='CS-01-G')return letter==='A'?UI_LABELS.tooltipCutsceneGDefense:letter==='B'?UI_LABELS.tooltipCutsceneGOffense:UI_LABELS.tooltipCutsceneGPact;if(id.startsWith('CS-G'))return UI_LABELS.tooltipCutsceneGoguryeo+'\n'+String(label);return UI_LABELS.tooltipCutsceneNone+'\n'+String(label)}
function renderCutscene(id){$('btn-cutscene-close').textContent='닫기';const scene=CUTSCENES[id];if(!scene){state.eventOpen=false;return}state.quests.pendingScene=id;const parsed=state.quests.dialogues[id]||scene;const title=parsed.title||scene.title,lines=parsed.lines?.length?parsed.lines:scene.lines;$('cutscene-kicker').textContent=`${id} · 사극 컷신`;$('cutscene-title').textContent=title;const lineBox=$('cutscene-lines');lineBox.replaceChildren();for(const [speaker,mood,text]of lines){const div=document.createElement('div');div.className='dialogue-line';div.dataset.mood=(mood.split(/[?>]/).at(-1)||"neutral").toLowerCase();div.innerHTML=`<span class="speaker">${escapeHtml(displaySpeaker(speaker,id))}</span><span class="mood">${escapeHtml(displayEmotion(mood))}</span><br>${escapeHtml(text)}`;lineBox.append(div)}const choices=$('cutscene-choices');choices.replaceChildren();let options=[];if(id==='CS-01')options=scene.choices.map(([letter,label,value])=>[letter,label,()=>finishTreaty(value)]);if(id==='CS-01-G'||id==='CS-G2'||id==='CS-G3'||id==='CS-G4')options=scene.choices.map(([letter,label,value])=>[letter,label,()=>finishGoguryeoChoice(id,value)]);if(id==='CS-02-S')options=scene.choices.map(([letter,label,value])=>[letter,label,()=>finishRaid(value)]);if(id==='CS-02-B')options=scene.choices.map(([letter,label,value])=>[letter,label,()=>finishBaekjeResponse(value)]);if(id==='CS-04')options=scene.baekjeChoices.map(([letter,label,value])=>[letter,`백제 · ${label}`,()=>{state.quests.seongwangChoice=value;renderAll();showCutsceneSillaHalf()}]);for(const [letter,label,action]of options){const button=document.createElement('button');button.textContent=`${({A:'🅰️',B:'🅱️',C:'🅲️'}[letter]||letter)} · ${label}`;button.dataset.tooltip=id==='CS-01'?(letter==='A'?UI_LABELS.tooltipCutsceneHigh:letter==='B'?UI_LABELS.tooltipCutsceneLow:UI_LABELS.tooltipCutsceneNone):cutsceneTip(id,letter,label);const preview=document.createElement('small');preview.className='choice-preview';preview.textContent='👉 '+button.dataset.tooltip.split(/\n/).map(x=>x.replace(/^[^:]+:\s*/, '')).join(' · ');button.append(preview);button.onclick=action;choices.append(button)}setupCutscenePages(id,Boolean(options.length));$('btn-cutscene-close').style.display=options.length?'none':'inline-block';$('cutscene-modal').showModal()}
function showCutsceneSillaHalf(){const id='CS-04',scene=CUTSCENES[id],choices=$('cutscene-choices');$('cutscene-kicker').textContent='CS-04 · 관산성의 밤';$('cutscene-title').textContent=scene.title;const lineBox=$('cutscene-lines');lineBox.replaceChildren(...scene.lines.map(([speaker,mood,text])=>{const div=document.createElement('div');div.className='dialogue-line';div.dataset.mood=(mood.split(/[?>]/).at(-1)||"neutral").toLowerCase();div.innerHTML=`<span class="speaker">${escapeHtml(displaySpeaker(speaker,id))}</span><span class="mood">${escapeHtml(displayEmotion(mood))}</span><br>${escapeHtml(text)}`;return div}));choices.replaceChildren(...scene.sillaChoices.map(([letter,label,value])=>{const button=document.createElement('button');button.textContent=`${({A:'🅰️',B:'🅱️',C:'🅲️'}[letter]||letter)} · ${label}`;button.dataset.tooltip=value==='CAPTURED'?UI_LABELS.tooltipCutsceneCapture:value==='DIES'?UI_LABELS.tooltipCutsceneDeath:UI_LABELS.tooltipCutsceneSpare;const preview=document.createElement('small');preview.className='choice-preview';preview.textContent='👉 '+button.dataset.tooltip.split(/\n/).map(x=>x.replace(/^[^:]+:\s*/, '')).join(' · ');button.append(preview);button.onclick=()=>finishGwansan(state.quests.seongwangChoice||'ATTEND',value);return button}));setupCutscenePages('CS-04-SILLA',true)}
function closeCutscene(){const id=state.quests.pendingScene;if(id?.startsWith('CS-'))state.quests.cutscenes.add(id);$('cutscene-modal').close();state.quests.pendingScene=null;state.eventOpen=false;renderAll();queueMicrotask(pumpStoryQueue)}
const SIDEQUEST_DIALOGUE={
  'SQ-01':['육두품 인재','neutral','율령은 백성을 하나로 묶으나, 골품의 벽은 아직 높사옵니다. 재능 있는 자를 조정에 들이시겠습니까?'],
  'SQ-02':['담로 사신','neutral','왕족을 지방에 보내 다스릴지, 교역 허가로 민심을 얻을지 결정해 주십시오.'],
  'SQ-03':['대가야 수장','whisper→worried','두 나라에 서로 다른 약속을 했소. 밀서를 감추면 가야가 숨을 돌리지만, 한쪽에 내보이면 다른 쪽은 등을 돌릴 것이오.'],
  'SQ-04':['고구려 밀사','whisper','한강의 형세가 기울고 있소. 밀약으로 서로의 칼끝을 거두겠소, 아니면 제안을 거부하겠소?'],
  'SQ-05':['젊은 무관','excited','첫 전장에 나설 준비가 되었습니다. 이사부 장군의 훈련을 더 받을지, 선봉에 설지 명해 주십시오.']
};
function renderSideQuestEvent(id){const quest=SIDE_QUESTS.find(item=>item.id===id),line=SIDEQUEST_DIALOGUE[id];if(!quest||!line){state.eventOpen=false;return}$('cutscene-kicker').textContent=`${id} · 행동 이벤트`;$('cutscene-title').textContent=quest.title;const box=$('cutscene-lines'),div=document.createElement('div');div.className='dialogue-line';div.dataset.mood=line[1].split(/[?>]/).at(-1).toLowerCase();div.innerHTML=`<span class="speaker">${escapeHtml(displaySpeaker(line[0],id))}</span><span class="mood">${escapeHtml(displayEmotion(line[1]))}</span><br>${escapeHtml(line[2])}`;box.replaceChildren(div);const choices=$('cutscene-choices');choices.replaceChildren(...quest.choices.map((choice,index)=>{const button=document.createElement('button');button.textContent=`${({0:'🅰️',1:'🅱️',2:'🅲️'}[index])} · ${choice.label}`;button.onclick=()=>applySideQuest(id,choice.id,true);return button}));$('btn-cutscene-continue').style.display='none';$('btn-cutscene-close').style.display='none';$('cutscene-modal').showModal()}
function setTrust(value){state.trust=Math.max(0,Math.min(100,value));if(state.trust<=40){setRelation(state,'SILLA','BAEKJE','WAR');state.allianceBroken=true}checkActionTriggers('trust')}
function finishTreaty(value){state.flags.treatyClarity=value;setTrust(value==='HIGH'?70:value==='LOW'?60:65);chronicle('MQ-01',value,`TREATY_clarity=${value}; trust ${state.trust}`);state.quests.path.push(`CS-01 맹약: ${value}`);state.quests.completed.add('MQ-01');state.quests.cutscenes.add('CS-01');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=1;state.eventOpen=false;addLog(`협정 분기 확정: TREATY_clarity=${value}, 신뢰 ${state.trust}.`);renderAll();queueMicrotask(pumpStoryQueue)}
function finishGoguryeoChoice(sceneId,value){chronicle(`MQ-G${state.quests.mainIndex+1}`,value,`${sceneId}=${value}`);state.quests.path.push(`${sceneId}: ${value}`);if(sceneId==='CS-01-G'){state.goguryeoStance=value;if(value==='DEFENSE'){state.defenseBonus=1.3;state.attackBonus=1}else if(value==='OFFENSE'){state.attackBonus=1.3;state.defenseBonus=1}else{state.quests.unlockedPact=true}state.quests.completed.add('MQ-G1');state.quests.cutscenes.add(sceneId);state.quests.mainIndex=1;state.triggers.goguryeoNextTurn=state.turn+1}else if(sceneId==='CS-G2'){state.flags.goguryeoPact=value==='PACT';state.quests.completed.add('MQ-G2');state.quests.mainIndex=2;state.triggers.goguryeoNextTurn=state.turn+1}else if(sceneId==='CS-G3'){state.quests.goguryeoCounterTarget=value;state.quests.completed.add('MQ-G3');state.quests.mainIndex=3;state.triggers.goguryeoNextTurn=state.turn+1}else{state.quests.completed.add('MQ-G4');state.quests.mainIndex=4;state.quests.ending={id:value,title:value==='HEGEMONY'?'삼한 패권 회복':value==='BALANCE'?'제가회의의 균형':'한강 방어선의 승리',summary:'양원왕과 제가회의가 선택한 방책이 고구려의 다음 시대를 결정했습니다.'};$('cutscene-modal').close();state.quests.pendingScene=null;state.eventOpen=false;renderAll();showEnding();return}$('cutscene-modal').close();state.quests.pendingScene=null;state.eventOpen=false;addLog(`고구려 전용 임무 ${sceneId} 선택: ${value}`);renderAll();queueMicrotask(pumpStoryQueue)}
function finishRaid(value){chronicle('MQ-02',value,`SILLA_raid_scope=${value}`);state.flags.sillaRaidScope=value;setTrust(value==='FULL'?25:58);state.quests.path.push(`CS-02-S 신라 선택: ${value}`);if(value==='FULL'){const tile=findTileByNodeId(state,'danghang');if(tile){const oldOwner=tile.owner;tile.owner='SILLA';onTileCaptured(oldOwner,'SILLA',tile,null)}state.allianceBroken=true;setRelation(state,'SILLA','BAEKJE','WAR');state.hanseongTrigger=true;for(const army of state.armies.filter(a=>a.owner==='BAEKJE'))army.ap=0;addLog('신라가 한강 하류를 전부 취했습니다. 백제와의 동맹이 파기되고 관산성 방면 적대 진격이 시작됩니다.')}else if(value==='DELEGATE'){state.flags.sillaRaidScope='PARTIAL';state.isabuRelation=Math.min(100,state.isabuRelation+15)}state.quests.completed.add('MQ-02');state.quests.cutscenes.add('CS-02-S');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=2;state.eventOpen=false;addLog(`SILLA_raid_scope=${state.flags.sillaRaidScope}.`);renderAll()}
function finishBaekjeResponse(value){chronicle('MQ-02',value,`BAEKJE_response=${value}`);state.flags.baekjeResponse=value;setTrust(value==='PREEMPT'?55:value==='IGNORE'?35:45);if(value==='DELEGATE')state.isabuRelation=Math.min(100,state.isabuRelation+10);state.quests.path.push(`CS-02-B 백제 선택: ${value}`);state.quests.completed.add('MQ-02');state.quests.cutscenes.add('CS-02-B');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=2;state.eventOpen=false;addLog(`BAEKJE_response=${value}.`);renderAll()}
function finishGwansan(kingChoice,action){const outcome=kingChoice==='ABSENT'?(action==='SPARED'?'KING_SPARED':'KING_ABSENT'):({CAPTURED:'KING_CAPTURED',DIES:'KING_DIES',SPARED:'KING_SPARED'}[action]||action);state.flags.gwansanOutcome=outcome;chronicle('MQ-04',`${kingChoice} / ${action}`,`GWANSAN_outcome=${outcome}`);state.quests.path.push(`CS-04 성왕 ${kingChoice} × 신라 ${action} → ${outcome}`);state.quests.completed.add('MQ-04');state.quests.cutscenes.add('CS-04');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=4;state.eventOpen=false;state.quests.ending=chooseEnding();addLog(`GWANSAN_outcome=${outcome}. 선택의 결산: ${state.quests.ending.title}`);renderAll();showEnding()}
function showEnding(){const ending=state.quests.ending;if(!ending)return;$('ending-title').textContent=`${ending.hidden?'히든 엔딩 · ':`엔딩 ${ending.id} · `}${ending.title}`;$('ending-summary').innerHTML=`<div class="ending-outcome">${ending.summary}</div><div class="ending-path"><b>선택 경로</b><br>${state.quests.path.map(escapeHtml).join('<br>')||'기록된 선택 없음'}</div><ul class="ending-epilogue"><li>${state.quests.sq01Survives===null?'SQ-01 인물 경로 미선택':state.quests.sq01Survives}</li><li>${state.quests.sq05Survives===null?'SQ-05 화랑 경로 미선택':state.quests.sq05Survives}</li></ul>`;$('ending-modal').showModal()}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function chooseEnding(){const f=state.flags;if(f.goguryeoPact&&f.gwansanOutcome!=='KING_DIES')return{id:'H-NORTH',title:'북방의 그림자',hidden:true,summary:'고구려와의 암묵적 밀약으로 신라가 전력을 아껴 우위를 얻습니다. 이 진실은 역사에 기록되지 않습니다.'};if(f.gayaFavorBaekje>=40&&f.gayaFavorSilla>=40)return{id:'H-IRON',title:'쇠의 나라',hidden:true,summary:'대가야는 두 강국 어디에도 완전히 흡수되지 않고 교역 거점으로 독자 지위를 지킵니다.'};if(f.treatyClarity==='NONE'&&f.sillaRaidScope==='FULL'&&f.gwansanOutcome==='KING_DIES')return{id:'C',title:'끊어진 저울',summary:'신뢰가 무너진 두 나라는 소모전에 묶이고 가야는 그 틈에서 흡수되거나 고립됩니다.'};if(f.treatyClarity==='HIGH'&&f.sillaRaidScope==='PARTIAL'&&['KING_CAPTURED','KING_SPARED','KING_ABSENT'].includes(f.gwansanOutcome))return{id:'D',title:'유예된 전쟁',summary:'전면전은 피했지만 상처는 남았습니다. 두 나라의 갈등은 다음 세대의 숙제로 이어집니다.'};if(f.gwansanOutcome==='KING_DIES')return{id:'A',title:'중흥의 대가',summary:'성왕은 전사했으나 그 죽음이 백제를 한동안 결집시킵니다. 여창은 복수심을 안고 즉위합니다.'};if(f.sillaRaidScope==='FULL'&&f.gwansanOutcome!=='KING_SPARED')return{id:'B',title:'삼한의 설계자',summary:'신라는 한강을 완전히 장악하고 통일의 발판을 마련하지만, 신의 없는 왕이라는 평가도 남습니다.'};return{id:'D',title:'유예된 전쟁',summary:'양국은 상처를 안고 물러섭니다. 완전한 파국은 피했으나 갈등은 다음 세대에 남습니다.'}}
function applySideQuest(questId,choiceId,fromEvent=false){const quest=SIDE_QUESTS.find(q=>q.id===questId),choice=quest?.choices.find(c=>c.id===choiceId);if(!quest||!choice||quest.faction!==state.playerFaction||state.quests.sideCompleted.has(questId))return;const reward=choice.reward;if(reward.gold)state.nationalGold+=reward.gold;if(reward.troops){const army=playerArmies()[0];if(army){army.troops+=reward.troops;army.maxTroops+=reward.troops}else state.nationalFood+=reward.troops}if(reward.legitimacy)state.legitimacy=Math.min(100,state.legitimacy+reward.legitimacy);if(reward.trust)setTrust(state.trust+reward.trust);if(reward.gayaBaekje)state.flags.gayaFavorBaekje=Math.max(0,Math.min(100,state.flags.gayaFavorBaekje+reward.gayaBaekje));if(reward.gayaSilla)state.flags.gayaFavorSilla=Math.max(0,Math.min(100,state.flags.gayaFavorSilla+reward.gayaSilla));if('pact'in reward)state.flags.goguryeoPact=reward.pact;if(reward.isabu)state.isabuRelation=Math.min(100,state.isabuRelation+reward.isabu);if(questId==='SQ-01')state.quests.sq01Survives=choice.epilogue;if(questId==='SQ-05')state.quests.sq05Survives=choice.epilogue;state.quests.sideCompleted.add(questId);state.quests.path.push(`${questId} ${quest.title}: ${choice.label}`);chronicle(questId,choice.label,JSON.stringify(reward));addLog(`${questId} 보상 적용: ${choice.label}`);if(fromEvent)closeCutscene();renderAll();if(questId==='SQ-03'&&state.flags.gayaFavorBaekje>=40&&state.flags.gayaFavorSilla>=40)addLog('가야가 두 강국 사이의 독자 생존 기반을 확보했습니다.')}
function triggerSideQuest(id){const quest=SIDE_QUESTS.find(item=>item.id===id);if(!quest||quest.faction!==state.playerFaction)return;const key=id.replace('-','').toLowerCase();if(state.triggers[key]||state.quests.sideCompleted.has(id))return;state.triggers[key]=true;enqueueStoryEvent('sidequest',id)}
function checkActionTriggers(cause='turn'){
  if(!state.started)return;
  if(cause==='turn'&&state.triggers.sq01Turn!==null&&state.turn>=state.triggers.sq01Turn&&state.playerFaction==='SILLA')triggerSideQuest('SQ-01');
  if(state.playerFaction==='BAEKJE'&&(state.trust<=50||state.turn>=4))triggerSideQuest('SQ-03');
  if(state.playerFaction==='GOGURYEO'&&state.goguryeoTilesLost>0)triggerSideQuest('SQ-04');
  if(state.playerFaction==='GOGURYEO'&&state.triggers.goguryeoNextTurn&&state.turn>=state.triggers.goguryeoNextTurn){const next=['CS-G2','CS-G3','CS-G4'][state.quests.mainIndex-1];state.triggers.goguryeoNextTurn=null;if(next)showCutscene(next)}
}
function markStateAction(action){if(!state.started)return;if(action==='silla-policy'&&state.playerFaction==='SILLA')state.triggers.sq01Turn=state.turn+1;if(action==='baekje-rear'&&state.playerFaction==='BAEKJE')triggerSideQuest('SQ-02');if(action==='army-raised'&&state.playerFaction==='BAEKJE')triggerSideQuest('SQ-02');if(action==='goguryeo-policy'&&state.playerFaction==='GOGURYEO')state.defenseBonus=(state.defenseBonus||1)+.1;checkActionTriggers(action)}
function onTileCaptured(previousOwner,newOwner,tile,army){if(['SILLA','BAEKJE','GOGURYEO'].includes(previousOwner)&&previousOwner!==newOwner)state.collapseCaptors[previousOwner]=newOwner;if(state.playerFaction==='GOGURYEO'&&newOwner==='GOGURYEO'&&previousOwner!=='GOGURYEO'&&state.quests.mainIndex===2){state.quests.goguryeoSouthTargetCaptured=true;state.triggers.goguryeoNextTurn=state.turn+1}if(state.playerFaction==='GOGURYEO'&&previousOwner==='GOGURYEO'&&newOwner!=='GOGURYEO'){state.goguryeoTilesLost++;state.goguryeoHanseongLost ||= tile.node?.id==='hanseong';triggerSideQuest('SQ-04')}if(tile.node?.id==='hanseong'&&previousOwner!==newOwner&&!state.quests.completed.has('MQ-02')){state.hanseongTrigger=true;if(newOwner==='SILLA'&&state.playerFaction==='SILLA'){state.allianceBroken=true;setRelation(state,'SILLA','BAEKJE','WAR');setTrust(Math.min(state.trust,25))}if(state.playerFaction==='SILLA'||state.playerFaction==='BAEKJE')showCutscene(state.playerFaction==='BAEKJE'?'CS-02-B':'CS-02-S')}}
function onBattleResolved(attacker,defender,tile,isPlayerBattle){const nations=new Set([attacker.owner,defender.owner]);const sillaBaekje=nations.has('SILLA')&&nations.has('BAEKJE');if((state.playerFaction==='SILLA'||state.playerFaction==='BAEKJE')&&sillaBaekje&&(tile.node?.id==='gwansan'||tile.node?.type==='FORT')&&!state.quests.completed.has('MQ-04'))showCutscene('CS-04');const han=findTileByNodeId(state,'hanseong');if(sillaBaekje&&han&&getDistance(tile.q,tile.r,han.q,han.r)<=1)state.triggers.hanseongBattleTurn=state.turn+1;if(isPlayerBattle&&state.playerFaction==='SILLA'&&!state.triggers.sq05)triggerSideQuest('SQ-05')}

function renderLobby(){const cards=$('faction-cards');cards.replaceChildren();for(const factionId of ['SILLA','BAEKJE','GOGURYEO']){const info=FACTION_CAMPAIGNS[factionId],button=document.createElement('button');button.className=`faction-card ${state.lobbyFaction===factionId?'active':''}`;button.style.borderTop=`4px solid ${info.color}`;button.innerHTML=`<strong>${FACTIONS[factionId].name}</strong><span>${info.leader}</span>`;button.onclick=()=>{state.lobbyFaction=factionId;state.lobbyClanId=info.royalClan;renderLobby()};cards.append(button)}const info=FACTION_CAMPAIGNS[state.lobbyFaction];state.lobbyClanId=info.royalClan;$('lobby-faction-name').textContent=`${FACTIONS[state.lobbyFaction].name} · ${info.leader}`;$('lobby-faction-traits').textContent=info.traits;$('lobby-difficulty').textContent=info.difficulty;$('lobby-summary').textContent=`${councilNameFor(state.lobbyFaction)}와 시작 가문을 선택한 뒤 출진하세요.`;const clans=$('lobby-clan-options');clans.replaceChildren();for(const [id,label]of [[info.royalClan,'왕실'],[info.nobleClan,'대귀족']]){const clan=state.clans[id],button=document.createElement('button');const locked=id!==info.royalClan;button.className=`lobby-clan ${locked?'locked active':''}`;button.disabled=locked;button.innerHTML=`<b>${label} · ${clan.name}</b><br><small>${clan.leader} · 사병 ${clan.privateArmy.toLocaleString()}명</small>${locked?`<span class="lobby-lock-badge">${UI_LABELS.lobbyNobleLock}</span>`:''}`;if(!locked)button.onclick=()=>{state.lobbyClanId=id;renderLobby()};clans.append(button)}}
function councilNameFor(factionId){return COUNCILS[factionId]||'귀족 회의'}
function startCampaignLegacy(){if(state.started)return;const faction=state.lobbyFaction,campaign=FACTION_CAMPAIGNS[faction],start=FACTION_START[faction],army=state.armies.find(a=>a.id===start.army);state.playerFaction=faction;state.activeClanId=state.lobbyClanId;state.selectedTileKey=army?tileKey(army.q,army.r):start.tile;state.started=true;state.northWarApproved=faction==='GOGURYEO';state.tileCardOpen=false;if(army)army.clanId=state.lobbyClanId;$('campaign-lobby').close();$('ui-faction-badge').textContent=`${FACTIONS[faction].name} · ${campaign.leader}`;addLog(`${FACTIONS[faction].name} ${campaign.leader} 캠페인 시작. 시작 가문: ${state.clans[state.activeClanId].name}.`);renderAll();if(state.narrativeReady)showCutscene(faction==='GOGURYEO'?'CS-01-G':'CS-01')}
function startCampaign(){startCampaignLegacy();state.warAgendaApproved=false;state.northWarApproved=false;renderAll()}
function switchTab(tab){document.querySelectorAll('.side-tab').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));document.querySelectorAll('.tab-content').forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===tab))}

function proposeWarAgenda(){if(!activeClan()?.isKing){addLog('왕실 가문으로 시작한 플레이어만 군사 의제를 상정할 수 있습니다.');return}if(state.northWarApproved){addLog('이미 군사 의제가 통과되었습니다.');return}if(state.warJustification<60){addLog('전쟁 명분 부족 ('+state.warJustification+'/60). 국제 정세 공작이나 국경 마찰이 필요합니다.');return}if(state.warJustification>=70&&state.nationalFood>=1200)for(const c of playerClans().filter(c=>!c.isKing&&!['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu','park_noble','baekje_sa','goguryeo_go'].includes(c.id)))c.loyalty=Math.max(55,c.loyalty);openWarStrategy()}
function strategyPlans(){if(state.playerFaction==='SILLA')return[{label:'대고구려 북진 공동전선',detail:'백제와 나제동맹을 유지하고 고구려에 선전포고합니다.',wars:['GOGURYEO'],allies:[['SILLA','BAEKJE','ALLIANCE']]},{label:'고구려 밀약 & 백제 기습',detail:'고구려와 3턴 밀약을 맺고 백제를 기습합니다. 나제 신뢰도가 크게 하락합니다.',wars:['BAEKJE'],pacts:['GOGURYEO'],breakAlliance:true}];if(state.playerFaction==='BAEKJE')return[{label:'한성 고토 수복전',detail:'신라와 동맹을 유지하고 고구려에 선전포고합니다.',wars:['GOGURYEO'],allies:[['SILLA','BAEKJE','ALLIANCE']]},{label:'대가야 철기 연맹 & 신라 견제전',detail:'대가야와 군사 동맹을 맺고 신라를 공격합니다.',wars:['SILLA'],allies:[['BAEKJE','GAYA','ALLIANCE']],breakAlliance:true}];return[{label:'한성 사수 및 백제 주력 격파전',detail:'신라에 3턴 밀약을 보내고 백제에 역습합니다.',wars:['BAEKJE'],pacts:['SILLA']},{label:'남진 전면전 · 신라',detail:'밀약 없이 신라에 전면전을 선포합니다.',wars:['SILLA']},{label:'남진 전면전 · 양국 모두',detail:'신라와 백제 양국에 동시에 전면전을 선포합니다.',wars:['SILLA','BAEKJE']}]}
function openWarStrategy(){let dialog=document.getElementById('diplomacy-strategy');if(!dialog){dialog=document.createElement('dialog');dialog.id='diplomacy-strategy';document.body.append(dialog)}const plans=strategyPlans();dialog.innerHTML='<h2>출병 및 외교 전략 의제</h2><p>먼저 동맹과 밀약, 전쟁 대상을 선택하십시오. 귀족 회의가 승인하기 전까지 관계는 바뀌지 않습니다.</p><div class="world-brief"><b>전쟁 명분 '+state.warJustification+'/100 · 한강 전운 '+state.worldTension+'/100</b><p>'+worldBriefingText()+'</p></div>'+plans.map((p,i)=>'<button class="strategy-option" data-plan="'+i+'"><b>'+(i+1)+'. '+p.label+'</b><br><small>'+p.detail+'</small></button>').join('')+'<div class="btn-row"><button id="strategy-cancel">돌아가기</button></div>';dialog.querySelectorAll('[data-plan]').forEach(button=>button.onclick=()=>{const plan=plans[Number(button.dataset.plan)];dialog.close();openCouncilDebateV043(plan)});dialog.querySelector('#strategy-cancel').onclick=()=>dialog.close();dialog.showModal()}
function councilSpeech(c){if(['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu'].includes(c.id))return state.promisedLandClanId===c.id?'한성 땅을 우리 가문에 약속하신다면 선봉에 서겠소!':'전공과 점령지를 보장하신다면 군사를 내겠소.';if(['park_noble','baekje_sa','goguryeo_go'].includes(c.id))return'명분도 없이 군사를 일으키면 백성이 등을 돌립니다.';return state.warJustification>=70&&state.nationalFood>=1200?'대의와 군량이 갖춰졌으니 찬성하겠습니다.':'명분과 군량부터 갖추십시오. 경솔한 출병은 나라를 위태롭게 합니다.'}
function openCouncilDebateV043(plan){state.pendingWarPlan=plan;let dialog=document.getElementById('council-debate');if(!dialog){dialog=document.createElement('dialog');dialog.id='council-debate';document.body.append(dialog)}const nobles=playerClans().filter(c=>!c.isKing),dissent=nobles.filter(c=>c.loyalty<55),support=nobles.length-dissent.length;dialog.innerHTML='<h2>'+councilName()+' · 출병 어전회의</h2><section class="world-brief"><b>선택 노선: '+plan.label+'</b><p>'+plan.detail+'</p><b>한강 전운 '+state.worldTension+'/100 · 전쟁 명분 '+state.warJustification+'/100</b><p>'+worldBriefingText()+'</p></section><p>찬성 '+support+'/'+nobles.length+' · 반대·보류 '+dissent.length+'</p>'+nobles.map(c=>'<p><b>'+c.name+' ('+c.leader+')</b> — “'+councilSpeech(c)+'”</p>').join('')+'<div class="btn-row"><button id="council-trade">A · 이권 양보 (왕권 -10, 대표 가문 사병 +300)</button><button id="council-bribe">B · 국고 회유 (금 -150, 군량 -200, 충성 +20)</button><button id="council-force" class="btn-danger">C · 왕명으로 강행 (민심 -15, 귀족 충성 -20)</button><button id="council-cancel">돌아가기</button></div>';const target=dissent[0]||nobles[0];dialog.querySelector('#council-trade').dataset.tooltip=UI_LABELS.tooltipCouncilTrade;dialog.querySelector('#council-bribe').dataset.tooltip=UI_LABELS.tooltipCouncilBribe;dialog.querySelector('#council-force').dataset.tooltip=UI_LABELS.tooltipCouncilForce;dialog.querySelector('#council-trade').onclick=()=>{if(target){state.royalAuth=Math.max(0,state.royalAuth-10);target.privateArmy+=300;target.loyalty=Math.min(100,target.loyalty+25)}passCouncil(dialog,'정치적 타협으로 출병 의제를 통과시켰습니다.')};dialog.querySelector('#council-bribe').onclick=()=>{if(state.nationalGold<150||state.nationalFood<200){addLog('회유에는 금 150과 군량 200이 필요합니다.');return}state.nationalGold-=150;state.nationalFood-=200;for(const c of dissent)c.loyalty=Math.min(100,c.loyalty+20);if(nobles.filter(c=>c.loyalty>=55).length>nobles.length/2)passCouncil(dialog,'국고 회유로 귀족 과반의 동의를 얻었습니다.');else addLog('회유 후에도 과반에 미달합니다. 추가 협의가 필요합니다.');renderAll()};dialog.querySelector('#council-force').onclick=()=>{state.legitimacy=Math.max(0,state.legitimacy-15);for(const c of nobles)c.loyalty=Math.max(0,c.loyalty-20);passCouncil(dialog,'왕명으로 출병을 강행했습니다. 내전 위기가 커집니다.')};dialog.querySelector('#council-cancel').onclick=()=>{state.pendingWarPlan=null;dialog.close()};dialog.showModal()}
function passCouncil(dialog,message){const plan=state.pendingWarPlan;if(plan){for(const target of plan.wars)setRelation(state,state.playerFaction,target,'WAR');for(const [a,b,status]of plan.allies||[]){setRelation(state,a,b,status);if(status==='ALLIANCE'){const partner=a===state.playerFaction?b:a;for(const target of plan.wars)if(target!==partner)setRelation(state,partner,target,'WAR')}}for(const target of plan.pacts||[])setRelation(state,state.playerFaction,target,'SECRET_PACT',state.turn+3,'3턴 밀약');if(plan.breakAlliance){setRelation(state,'SILLA','BAEKJE','WAR');state.allianceBroken=true;setTrust(Math.min(state.trust,25))}state.warTargets=[...plan.wars];addLog('외교 노선 확정: '+plan.label+'. 전쟁 대상: '+plan.wars.map(f=>FACTIONS[f].name).join(', ')+'.')}state.pendingWarPlan=null;state.warAgendaApproved=true;state.northWarApproved=true;dialog.close();addLog(message);renderAll()}
function worldBriefingText(){return state.lastWorldBriefing||'한강 유역의 정세를 살피는 중입니다.'}
function metricStatus(metric,value){if(metric==='royalAuth')return value>=60?['충분함(안정)','good']:value>=40?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='nationalFood')return value>=800?['충분함(안정)','good']:value>=300?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='nationalGold')return value>=300?['충분함(안정)','good']:value>=150?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='trust')return value>=60?['충분함(안정)','good']:value>40?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='mandate')return value>=70?['충분함(안정)','good']:value>30?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='warJustification')return value>=60?['충분함(안정)','good']:value>=40?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='worldTension')return value<40?['충분함(안정)','good']:value<70?['보통(주의)','warn']:['위험(부족)','bad'];return value>=55?['충분함(안정)','good']:value>30?['보통(주의)','warn']:['위험(부족)','bad']}
function monthlyEconomyEstimate(){let food=180,gold=90;for(const tile of Object.values(state.tiles))if(tile.owner===state.playerFaction&&tile.node){if(tile.node.type==='CAPITAL'){food+=120;gold+=80}else if(tile.node.type==='TOWN'){food+=70;gold+=40}else if(tile.node.type==='PORT')gold+=90}const foodUse=playerArmies().filter(a=>a.supplied&&a.troops<a.maxTroops).length*100;return{food,gold,foodNet:food-foodUse,foodUse}}
function metricBriefing(metric){const economy=monthlyEconomyEstimate();if(metric==='iron'||metric==='horses'){const iron=metric==='iron',value=iron?state.iron:state.horses;return{title:iron?'철':'군마',level:value>=80?'충분함(안정)':value>=30?'보통(주의)':'위험(부족)',tone:value>=80?'good':value>=30?'warn':'bad',value:'현재 '+value,delta:'매 턴 보유 생산 거점마다 '+(iron?12:10)+'씩 생산합니다.',impact:iron?'중장보병 편성에 철 40, 기병 편성에 철 50이 필요합니다.':'기병 편성마다 군마 50필이 필요합니다.',action:iron?'웅산 철광·울산 제철항·합천 철성을 점령하십시오.':'춘천 목장을 점령하십시오.'}}if(metric.startsWith('relation:')){const faction=metric.slice(9),relation=getRelation(state,state.playerFaction,faction),status=DIPLOMACY_STATUS[relation.status]||DIPLOMACY_STATUS.NEUTRAL,[level,tone]=relation.status==='WAR'?['교전 중','bad']:relation.status==='ALLIANCE'?['동맹','good']:relation.status==='SECRET_PACT'?['밀약 유지','good']:['경계·대치','warn'];return{title:FACTIONS[faction]?.name+' 외교 관계',level,tone,value:status.label,delta:relation.expiresAt?'밀약 만료까지 '+Math.max(0,relation.expiresAt-state.turn)+'턴 남았습니다.':'이번 턴 관계 만료 없음.',impact:'동맹·밀약·중립국 영토는 진입할 수 없고, WAR 상태인 국가에만 공격과 점령이 허용됩니다.',action:relation.note||'관계는 출병 전략 의제에서 변경합니다.'}}if(metric.startsWith('clan:')){const clan=state.clans[metric.slice(5)];if(!clan)return null;const [level,tone]=metricStatus('clan',clan.loyalty),martial=['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu'].includes(clan.id),conservative=['park_noble','baekje_sa','goguryeo_go'].includes(clan.id),promised=state.promisedLandClanId===clan.id?'점령지 분봉 서약이 걸려 있습니다.':state.marriageContracts?.has(clan.id)?'정략혼인 동맹으로 결속되어 있습니다.':martial?'무장파: 점령지 분봉 약속으로 충성 +25, 출병 동의를 얻을 수 있습니다.':conservative?'보수 명문가: 정략혼인(충성 +30) 또는 3턴 조세 감면(충성 +15)으로 포섭할 수 있습니다.':'신중파: 명분 70 및 군량 1,200을 갖추거나 전략 군사권을 위임해 설득할 수 있습니다.';return{title:clan.name,region:clan.region,famousFor:clan.famousFor,lore:clan.lore,level,tone,value:'충성도 '+clan.loyalty+'% · 사병 '+clan.privateArmy.toLocaleString()+'명',delta:'충성도는 매 턴 고정 변동이 없고, 회의 거래·정책·전투 사건에 따라 바뀝니다.',impact:'충성도 55% 이상은 회의 찬성, 31~54%는 보류, 30% 이하는 반란 위험입니다. 사병은 가문 봉토의 독자 군사력입니다.',action:promised}}
 let value=0,title='',delta='',impact='',action='';switch(metric){case'royalAuth':value=state.royalAuth;title='왕권';delta='정기적인 고정 변동은 없습니다. 율령·중앙집권 개혁은 +10, 정략혼인은 -12, 정치적 타협은 -10입니다.';impact='60% 이상이면 율령 반포로 귀족 사병을 흡수할 수 있습니다. 40% 이하는 대귀족 정변 위험 구간입니다.';action='현재 '+value+'% ('+(value>=60?'왕권 우세':value>=40?'균형 상태':'정변 위험')+'). 가문과 혼인할 때 왕권 -12%를 감수합니다.';break;case'nationalFood':value=state.nationalFood;delta='다음 턴 예상: 군량 +'+economy.food+' 생산, 보충 중인 군단 '+economy.foodUse+' 소모 (순증 '+economy.foodNet+').';impact='새 군단 창설에는 300, 병력 보충에는 보충 군단마다 100이 필요합니다.';action='현재 '+value.toLocaleString()+' ('+(value>=800?'충분함':'부족 주의')+' - 신규 군단 약 '+Math.floor(value/300)+'회 소집 가능).';title='군량';break;case'nationalGold':value=state.nationalGold;delta='다음 턴 예상 국고 수입 +'+economy.gold+' (보유 거점 기준).';impact='신규 군단 창설 200금, 어전회의 회유 150금, 전쟁 명분 공작 80금에 사용합니다.';action='현재 '+value.toLocaleString()+' ('+(value>=300?'충분함':'주의')+').';title='국고';break;case'trust':value=state.trust;delta='정기 변동은 없으며 외교 선택과 사건에 따라 바뀝니다.';impact='60 이상이면 견고한 나제동맹이며 엔딩 D 조건에 기여합니다. 40 이하는 동맹 파기·관산성 기습 위험입니다.';action='현재 '+value+'/100 ('+(value>=60?'견고한 동맹':value>40?'흔들리는 동맹':'파기 위험')+').';title='나제동맹 신뢰도';break;case'mandate':value=state.legitimacy;delta='정기 고정 변동은 없으며 왕명 강행·국경 사건·정책으로 변합니다.';impact='70 이상이면 전 군단 사기 회복 +5 보너스가 적용됩니다. 왕명 강행은 -15, 30 이하는 민란 위험입니다.';action='현재 '+value+'/100 ('+(value>=70?'백성의 지지 높음':value>30?'주의':'민란 위험')+').';title='천명·민심';break;case'warJustification':value=state.warJustification;delta='통상 턴에는 변동 없음. 정세 사건·국경 대응·공작으로 증가합니다.';impact='60 이상이어야 출병·외교 전략 의제를 상정할 수 있습니다. 70 이상이면 군량 1,200 이상 보유 시 신중파가 찬성합니다.';action='현재 '+value+'/100. 부족 시 국경 공작(금 80, +25), 옛 강역 선포(민심 -8, +20), 국경 사건 대응을 이용하십시오.';title='전쟁 명분';break;case'worldTension':value=state.worldTension;delta='북방·해상·국경 정세 이벤트가 발생하면 변합니다.';impact='전운이 높을수록 외교 위기와 전쟁 이벤트가 자주 표면화됩니다.';action=state.lastWorldBriefing;title='한강 전운';break;default:return null}const [level,tone]=metricStatus(metric,value);return{title,level,tone,value:metric==='nationalGold'||metric==='nationalFood'?'현재 '+value.toLocaleString():`현재 ${value}/100`,delta,impact,action}}
function renderMetricInspector(metric){const info=metricBriefing(metric),card=$('metric-inspector');if(!info)return;card.hidden=false;const lore=info.lore?`<div class="clan-lore"><b>${UI_LABELS.loreRegion}:</b> ${escapeHtml(info.region)}<br><b>${UI_LABELS.loreFamous}:</b> ${escapeHtml(info.famousFor)}<p><b>${UI_LABELS.loreDisposition}</b><br>${escapeHtml(info.lore)}</p></div>`:'';$('metric-inspector-content').innerHTML=`<div class="section-title">${escapeHtml(info.title)} ${UI_LABELS.metricDetailsHeading}</div>${lore}<div class="metric-status ${info.tone}">${escapeHtml(info.level)}</div><p><b>${escapeHtml(info.value)}</b></p><p><b>${UI_LABELS.metricDeltaHeading}</b><br>${escapeHtml(info.delta)}</p><p><b>${UI_LABELS.metricImpactHeading}</b><br>${escapeHtml(info.impact)}</p><p><b>${UI_LABELS.metricActionHeading}</b><br>${escapeHtml(info.action)}</p>`}
function refreshMetricTooltips(){document.querySelectorAll('[data-metric]').forEach(el=>{const info=metricBriefing(el.dataset.metric);if(info)el.title=info.title+' · '+info.value+' · '+info.level+' — 클릭하여 상세 브리핑'})}
function renderRelations(){const statusBox=$('diplomacy-status');statusBox.innerHTML=statusBox.innerHTML.replace('백제-신라 신뢰 '+state.trust+'/100','<span data-metric="trust" tabindex="0">백제-신라 신뢰 '+state.trust+'/100</span>');const labels=statusBox.querySelectorAll('b');if(labels[0])labels[0].dataset.metric='warJustification';if(labels[1])labels[1].dataset.metric='worldTension';const box=$('relations-overview');if(!box)return;const others=['SILLA','BAEKJE','GOGURYEO','GAYA'].filter(f=>f!==state.playerFaction);box.innerHTML='<div class="relation-list">'+others.map(f=>{const relation=getRelation(state,state.playerFaction,f),status=DIPLOMACY_STATUS[relation.status]||DIPLOMACY_STATUS.NEUTRAL,expiry=relation.expiresAt?' · '+Math.max(0,relation.expiresAt-state.turn)+'턴 남음':'';return'<button class="relation-chip '+relation.status.toLowerCase()+'" data-metric="relation:'+f+'">'+status.icon+' '+FACTIONS[f].name+' · '+status.label+expiry+'</button>'}).join('')+'</div>'}
function runWorldTensionTurn(){if(state.worldEventTurn===state.turn)return;state.worldEventTurn=state.turn;if(state.turn%3===0){const weak=playerArmies().filter(a=>!a.supplied).length,disloyal=playerClans().filter(c=>!c.isKing&&c.loyalty<50).sort((a,b)=>a.loyalty-b.loyalty)[0],enemyTiles=Object.values(state.tiles).filter(t=>t.owner!==state.playerFaction).length;const title=weak?$('dynamic-title-supply').textContent:disloyal?$('dynamic-title-noble').textContent:$('dynamic-title-front').textContent;const summary=weak?$('dynamic-summary-supply').textContent.replace('{count}',weak):disloyal?$('dynamic-summary-noble').textContent.replace('{name}',disloyal.name).replace('{loyalty}',disloyal.loyalty):$('dynamic-summary-front').textContent.replace('{turn}',state.turn).replace('{tiles}',enemyTiles);let dialog=document.getElementById('dynamic-incident');if(!dialog){dialog=document.createElement('dialog');dialog.id='dynamic-incident';document.body.append(dialog)}dialog.innerHTML='<h2>'+title+'</h2><p>'+summary+'</p><div class="btn-row"><button id="dynamic-reinforce">'+$('dynamic-label-reinforce').textContent+'</button><button id="dynamic-claim">'+$('dynamic-label-claim').textContent+'</button></div>';dialog.querySelector('#dynamic-reinforce').onclick=()=>{if(state.nationalGold<100||state.nationalFood<200){addLog('증원에 필요한 국고 또는 군량이 부족합니다.');dialog.close();return}state.nationalGold-=100;state.nationalFood-=200;const army=spawnHouseArmy(activeClan(),600,'수도 구원군');dialog.close();addLog(`정세 사건: ${army?.name||'구원군'} 600명이 지도에 도착했습니다.`);renderAll()};dialog.querySelector('#dynamic-claim').onclick=()=>{state.warJustification=Math.min(100,state.warJustification+20);state.legitimacy=Math.max(0,state.legitimacy-2);dialog.close();addLog('정세 사건: 왕실 교서로 전쟁 명분이 20 상승했습니다.');renderAll()};dialog.showModal();return}const mod=state.turn%4;if(mod===2||mod===0){const event=mod===2?WORLD_TENSION_EVENTS.northern:WORLD_TENSION_EVENTS.maritime;state.warJustification=Math.min(100,state.warJustification+event.justification);state.worldTension=Math.min(100,state.worldTension+event.tension);state.lastWorldBriefing=`${mod===2?'🐎':'⛵'} [${event.title}] ${event.message} (전쟁 명분 +${event.justification})`;addLog(state.lastWorldBriefing);renderAll();return}const event=WORLD_TENSION_EVENTS.border;state.worldTension=Math.min(100,state.worldTension+event.tension);state.lastWorldBriefing=`🔥 [${event.title}] ${event.message}`;let dialog=document.getElementById('border-incident');if(!dialog){dialog=document.createElement('dialog');dialog.id='border-incident';document.body.append(dialog)}dialog.innerHTML=`<h2>${event.title}</h2><p>${event.message}</p><div class="btn-row"><button id="border-condemn">🅰️ 사신을 보내 규탄하고 명분을 쌓는다 (명분 +25)</button><button id="border-endure">🅱️ 참는다 (민심 -5, 동맹 신뢰 +10)</button></div>`;dialog.querySelector('#border-condemn').onclick=()=>{state.warJustification=Math.min(100,state.warJustification+event.justification);state.worldTension=Math.min(100,state.worldTension+5);state.lastWorldBriefing=`국경 약탈을 조정에 고발하여 정당한 대응 명분을 얻었습니다 (+${event.justification}).`;dialog.close();addLog(state.lastWorldBriefing);renderAll()};dialog.querySelector('#border-endure').onclick=()=>{state.legitimacy=Math.max(0,state.legitimacy-5);state.trust=Math.min(100,state.trust+10);state.worldTension=Math.max(0,state.worldTension-5);state.lastWorldBriefing='국경 충돌을 감내하고 동맹의 신뢰를 지켰습니다.';dialog.close();addLog(state.lastWorldBriefing);renderAll()};dialog.showModal()}
function proposeCentralize(){const clan=activeClan(),king=playerClans().find(c=>c.isKing);if(!clan?.isKing){if(state.playerFaction==='GOGURYEO'){state.defenseBonus=(state.defenseBonus||1)+.15;addLog('5부 귀족 통제와 태학 정비를 단행해 산성 방어 태세를 강화했습니다.')}else if(state.playerFaction==='BAEKJE'){state.damroInfluence=(state.damroInfluence||0)+1;addLog('22담로 왕족을 파견해 지방 통치와 대성팔족 견제를 강화했습니다.');markStateAction('army-raised')}renderAll();return}if(state.nationalGold<150)return addLog('개혁에는 국고 150이 필요합니다.');state.nationalGold-=150;state.royalAuth=Math.min(100,state.royalAuth+10);for(const noble of playerClans().filter(c=>!c.isKing)){const absorbed=Math.min(noble.privateArmy,300);noble.privateArmy-=absorbed;noble.loyalty=Math.max(0,noble.loyalty-12);let royalArmy=state.armies.find(a=>a.owner===state.playerFaction&&a.clanId===king.id);if(!royalArmy){const [q,r]=FACTION_START[state.playerFaction].tile.split(',').map(Number);royalArmy={id:`a_${state.playerFaction.toLowerCase()}_royal_${state.turn}`,name:`${FACTIONS[state.playerFaction].name} 왕실군`,owner:state.playerFaction,clanId:king.id,q,r,troops:0,maxTroops:0,morale:90,supplied:true,ap:2};state.armies.push(royalArmy)}royalArmy.troops+=absorbed;royalArmy.maxTroops+=absorbed}addLog(`${councilName()} 개혁: 왕권 +10, 대귀족 사병을 왕실군에 흡수했습니다.`);if(state.playerFaction==='SILLA')markStateAction('silla-policy');if(state.playerFaction==='GOGURYEO')markStateAction('goguryeo-policy');checkNobleRevoltRisk();renderAll()}
function rewardClan(id){const clan=state.clans[id];if(!activeClan()?.isKing||!clan||clan.faction!==state.playerFaction||clan.isKing||state.nationalGold<100)return addLog('왕실 시작 가문과 국고 100금을 확인하세요.');state.nationalGold-=100;clan.gold+=100;clan.loyalty=Math.min(100,clan.loyalty+18);addLog(`${clan.name}에 금 100을 하사했습니다. 충성도 ${clan.loyalty}%.`);if(state.playerFaction==='SILLA')markStateAction('silla-policy');checkNobleRevoltRisk();renderAll()}
function recruitPrivateTroops(){const clan=activeClan();if(!clan||clan.gold<100)return addLog('시작 가문 금고에 금 100이 필요합니다.');clan.gold-=100;clan.privateArmy+=400;addLog(`${clan.name}이 영지 자금으로 사병 400명을 모집했습니다.`);renderAll()}
function acceptRoyalOrder(){if(activeClan()?.isKing)return;state.coupMandate=false;state.royalAuth=Math.min(100,state.royalAuth+5);for(const c of playerClans().filter(c=>c.isKing))c.loyalty=Math.min(100,c.loyalty+5);addLog('왕실의 명령을 수용해 신임을 얻었습니다.');renderAll()}
function rejectRoyalOrder(){if(activeClan()?.isKing)return addLog('왕실 시작 가문은 왕실 명령 거부권을 행사할 수 없습니다.');state.coupMandate=true;state.royalAuth=Math.max(0,state.royalAuth-12);for(const c of playerClans().filter(c=>c.isKing))c.loyalty=Math.max(0,c.loyalty-8);addLog('왕실 명령을 거부했습니다. 찬탈 명분을 확보했으며 왕권이 하락했습니다.');renderAll()}
function launchCoup(){const clan=activeClan(),king=playerClans().find(c=>c.isKing);if(!hasCoupConditions())return addLog('정변 조건 미충족: 명분 확보 후 왕권 40 이하 또는 왕실군보다 사병 우위가 필요합니다.');if(!clan||!king)return;king.isKing=false;clan.isKing=true;state.coupMandate=false;state.royalAuth=55;addLog(`${clan.leader}이 정변을 일으켜 왕위를 찬탈했습니다.`);renderAll()}
function checkNobleRevoltRisk(){if(!state.started||!activeClan()?.isKing||state.revoltPending)return;const rebel=playerClans().find(c=>!c.isKing&&c.loyalty<=30);if(!rebel)return;state.revoltPending=true;enqueueStoryEvent('revolt',rebel.id)}
function renderRevoltEvent(clanId){const clan=state.clans[clanId];if(!clan){state.revoltPending=false;state.eventOpen=false;return}$('cutscene-kicker').textContent='정변 위기 · 귀족 반란';$('cutscene-title').textContent=`${clan.name}의 봉기` ;const line=document.createElement('div');line.className='dialogue-line';line.innerHTML=`<span class="speaker">${clan.leader}</span><span class="mood">[angry]</span><br>충성도 ${clan.loyalty}%까지 떨어진 귀족이 사병을 모아 왕실에 반기를 들었습니다.`;$('cutscene-lines').replaceChildren(line);const options=[['회유한다',()=>{state.nationalGold=Math.max(0,state.nationalGold-150);clan.loyalty=50;clan.privateArmy=Math.max(200,clan.privateArmy-200);addLog(`${clan.name}과 타협해 봉기를 진정시켰습니다.`)}],['왕실군으로 진압한다',()=>{const army=state.armies.find(a=>a.owner===state.playerFaction&&a.clanId===playerClans().find(c=>c.isKing)?.id);if(army){army.troops+=clan.privateArmy;army.maxTroops+=clan.privateArmy}clan.privateArmy=0;clan.loyalty=45;addLog(`${clan.name}의 사병을 해산하고 왕실군에 편입했습니다.`)}]];$('cutscene-choices').replaceChildren(...options.map(([label,action],i)=>{const button=document.createElement('button');button.textContent=`${i?'🅱️':'🅰️'} · ${label}`;button.onclick=()=>{action();state.revoltPending=false;state.eventOpen=false;$('cutscene-modal').close();renderAll();queueMicrotask(pumpStoryQueue)};return button}));$('btn-cutscene-continue').style.display='none';$('btn-cutscene-close').style.display='none';$('cutscene-modal').showModal()}

function raiseNewArmy(q,r,type=state.selectedUnitType||'INFANTRY'){const clan=activeClan(),unit=UNIT_TYPES[type]||UNIT_TYPES.INFANTRY;if(state.tiles[tileKey(q,r)]?.owner!==state.playerFaction)return addLog('자국 소유 거점에서만 군단을 창설할 수 있습니다.');if(state.nationalGold<unit.gold||state.nationalFood<unit.food||state.iron<(unit.iron||0)||state.horses<(unit.horse||0))return addLog('선택한 병종을 편성하기 위한 국고·군량·철·말이 부족합니다.');state.nationalGold-=unit.gold;state.nationalFood-=unit.food;state.iron-=unit.iron||0;state.horses-=unit.horse||0;state.armySeq++;const commander=state.generals.find(g=>g.faction===state.playerFaction);state.armies.push({id:`a_${state.playerFaction.toLowerCase()}_${state.armySeq}`,name:`${clan.leader} ${unit.label}군`,owner:state.playerFaction,clanId:clan.id,commanderId:commander?.id||null,unitType:type,q,r,troops:1800,maxTroops:2000,morale:100,supplied:true,ap:unit.ap});state.selectedArmyId=state.armies.at(-1).id;addLog(`${state.armies.at(-1).name}을 (${q},${r})에 창설했습니다.`);markStateAction('army-raised');renderAll()}
function chooseArmyType(q,r){let dialog=document.getElementById('recruit-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='recruit-dialog';document.body.append(dialog)}dialog.innerHTML=`<h2>신규 군단 병종 선택</h2><p>편성할 병종과 지불할 자원을 확인하십시오.</p><div class="unit-choice-grid">${Object.entries(UNIT_TYPES).map(([id,u])=>`<button data-unit="${id}"><b>${u.label}</b><small>금 ${u.gold} · 군량 ${u.food} · 철 ${u.iron||0} · 말 ${u.horse||0} · AP ${u.ap}</small></button>`).join('')}</div><button data-close>돌아가기</button>`;dialog.querySelectorAll('[data-unit]').forEach(button=>button.onclick=()=>{raiseNewArmy(q,r,button.dataset.unit);dialog.close()});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.showModal()}
function mergeArmiesOnTile(q,r){const stack=state.armies.filter(a=>a.q===q&&a.r===r&&a.owner===state.playerFaction);if(stack.length<2)return;const main=stack[0];for(const army of stack.slice(1)){main.troops+=army.troops;main.maxTroops+=army.maxTroops;main.ap=Math.min(main.ap,army.ap)}const remove=new Set(stack.slice(1).map(a=>a.id));state.armies=state.armies.filter(a=>!remove.has(a.id));state.selectedArmyId=main.id;addLog(`${stack.length}개 군단을 ${main.name}으로 병합했습니다.`);renderAll()}
function splitArmyById(id){const army=state.armies.find(item=>item.id===id&&item.owner===state.playerFaction);if(!army||army.troops<1000){addLog(UI_LABELS.splitUnavailable);return}const half=Math.floor(army.troops/2);army.troops-=half;army.maxTroops=Math.max(army.troops,Math.floor(army.maxTroops/2));state.armySeq++;const detachment={...army,id:`${army.id}_split_${state.armySeq}`,name:`${army.name} · ${state.armySeq} 분견대`,troops:half,maxTroops:Math.max(half,Math.ceil(army.maxTroops)),ap:army.ap};state.armies.push(detachment);state.selectedArmyId=detachment.id;addLog(`${army.name}에서 ${half.toLocaleString()}명을 분리해 새 군단을 편성했습니다.`);renderAll()}
function drawMoveOverlay(){const army=state.armies.find(a=>a.id===state.movingArmyId);if(!army)return;for(const tile of Object.values(state.tiles)){if(getDistance(army.q,army.r,tile.q,tile.r)!==1)continue;const{x,y}=hexToPixel(tile.q,tile.r),danger=isBlockedByEnemyFortZOC(state,tile,army.owner);drawHex(x,y,HEX_SIZE-2,'#00000000',danger?'#f97316':'#3fb950',4);if(danger){ctx.textAlign='center';ctx.fillStyle='#fb923c';ctx.font='bold 10px sans-serif';ctx.fillText('⚠️산성위협(사기-15·보급차단)',x,y+44)}}}
function startMoveArmy(id){const army=state.armies.find(a=>a.id===id);if(!army||army.owner!==state.playerFaction)return;if(army.ap<=0)return addLog('이 군단은 이번 달 행군력을 모두 사용했습니다.');state.movingArmyId=id;renderAll();drawMoveOverlay()}

function applyZocPenalty(army,tile){if(!isBlockedByEnemyFortZOC(state,tile,army.owner))return;army.morale=Math.max(0,army.morale-15);army.ap=0;army.supplied=false;army.zocSupplyCut=true;tile[`suppliedFor${army.owner}`]=false;addLog(`⚠️ ${army.name}이 산성 ZOC로 진입했습니다. 사기 -15, AP 소진, 보급 단절.`)}
function addBattleLog(attacker,defender,tile,result){addLog(`전투(${tile.node?.name||'야전'}): ${attacker.name} 손실 ${result.atkLoss.toLocaleString()} / ${defender.name} 손실 ${result.defLoss.toLocaleString()}${result.captured?' · 거점 함락':''}`)}
function openBattle(attacker,defender,tile,isAI=false){$('battle-modal').style.display='';if(!attacker||!defender||attacker.troops<=50||defender.troops<=50){const old=tile?.owner;state.armies=state.armies.filter(a=>a.troops>50);if(attacker&&defender&&tile&&attacker.troops>50&&defender.troops<=50&&!state.armies.some(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==attacker.owner)){attacker.q=tile.q;attacker.r=tile.r;tile.owner=attacker.owner;onTileCaptured(old,attacker.owner,tile,attacker);addLog(`${attacker.name} 무방비 타일을 점령했습니다.`)}state.movingArmyId=null;renderAll();return}const hasPlayer=attacker.owner===state.playerFaction||defender.owner===state.playerFaction;if(isAI&&!hasPlayer){const result=resolveBattle(state,attacker,defender,tile,'charge','formation',true);if(result.captured)applyZocPenalty(attacker,tile);addBattleLog(attacker,defender,tile,result);if(result.captured)onTileCaptured(result.previousOwner,attacker.owner,tile,attacker);renderAll();return}const pending={attackerId:attacker.id,defenderId:defender.id,tileKey:tileKey(tile.q,tile.r),isAI,playerSide:attacker.owner===state.playerFaction?'attacker':'defender'};if(!state.pendingBattles.some(p=>p.attackerId===pending.attackerId&&p.defenderId===pending.defenderId&&p.tileKey===pending.tileKey))state.pendingBattles.push(pending);if($('battle-modal').open)return;state.movingArmyId=null;const own=attacker.owner===state.playerFaction?attacker:defender;const dialog=$('battle-modal');$('battle-title').textContent=`전술 교전 · ${tile.node?.name||`(${tile.q},${tile.r})`}`;$('battle-summary').textContent=`${attacker.name} (${attacker.troops.toLocaleString()}명) vs ${defender.name} (${defender.troops.toLocaleString()}명)`;$('attacker-label').textContent=`내 전술 · ${own.name}`;$('defender-label').textContent=`적 전술 · ${own===attacker?defender.name:attacker.name}`;const box=document.querySelector('.tactic-options[data-side="player"]');box.replaceChildren();for(const [i,tactic]of (FACTION_TACTICS[own.owner]||FACTION_TACTICS.SILLA).entries()){const label=document.createElement('label');label.className='tactic-choice';label.innerHTML=`<input type="radio" name="player-tactic" value="${tactic.id}" ${i===0?'checked':''}><span>${tactic.name}</span>`;box.append(label)}dialog.showModal()}
function resolvePendingBattle(){const pending=state.pendingBattles.shift();if(!pending)return;const attacker=state.armies.find(a=>a.id===pending.attackerId),defender=state.armies.find(a=>a.id===pending.defenderId),tile=state.tiles[pending.tileKey];if(!attacker||!defender||!tile||attacker.troops<=50||defender.troops<=50){const old=tile?.owner;state.armies=state.armies.filter(a=>a.troops>50);if(attacker&&defender&&tile&&attacker.troops>50&&defender.troops<=50&&!state.armies.some(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==attacker.owner)){attacker.q=tile.q;attacker.r=tile.r;tile.owner=attacker.owner;onTileCaptured(old,attacker.owner,tile,attacker)}state.pendingBattles=[];state.movingArmyId=null;$('battle-modal').close();renderAll();return}const own=pending.playerSide==='attacker'?attacker:defender,enemy=own===attacker?defender:attacker,choice=document.querySelector('input[name="player-tactic"]:checked')?.value||'charge',enemyCards=FACTION_TACTICS[enemy.owner]||FACTION_TACTICS.SILLA,enemyCard=tile.node?.type==='FORT'?enemyCards.find(c=>c.type==='formation'):enemyCards[(enemy.troops+state.turn)%enemyCards.length],atk=own===attacker?choice:enemyCard.id,def=own===defender?choice:enemyCard.id,result=resolveBattle(state,attacker,defender,tile,atk,def,false),ownCard=(FACTION_TACTICS[own.owner]||FACTION_TACTICS.SILLA).find(c=>c.id===choice);if(result.captured)applyZocPenalty(attacker,tile);addBattleLog(attacker,defender,tile,result);addLog(`🗣️ ${own.name}: "진격하라!" · ${enemy.name}: "진형을 지켜라!" · 적 전술 공개: ${enemyCard.name} · ${result.advantage==='attacker'?'공격 우세 ×1.3':result.advantage==='defender'?'방어 우세 ×1.3':'호각 ×1.0'} · 아군 카드 ${ownCard?.name}`);if(result.captured)onTileCaptured(result.previousOwner,attacker.owner,tile,attacker);onBattleResolved(attacker,defender,tile,true);$('battle-modal').close();renderAll()}
function relationMessage(faction){const relation=getRelation(state,state.playerFaction,faction),name=FACTIONS[faction]?.name||faction,label=DIPLOMACY_STATUS[relation.status]?.label||'대치';return `🕊️ 현재 ${name}와는 [${label}] 상태입니다. 침공하려면 조정 회의에서 해당 국가에 대한 전쟁 의제를 통과시키거나 동맹을 파기해야 합니다.`}
function tryMoveOrAttack(tile){const army=state.armies.find(a=>a.id===state.movingArmyId);if(!army)return;if(getDistance(army.q,army.r,tile.q,tile.r)!==1){addLog('인접한 타일로만 이동할 수 있습니다.');state.movingArmyId=null;renderAll();return}if(tile.owner!==army.owner&&getRelation(state,army.owner,tile.owner).status!=='WAR'){addLog(relationMessage(tile.owner));state.movingArmyId=null;renderAll();return}const enemies=state.armies.filter(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==army.owner);const hostile=enemies.filter(a=>getRelation(state,army.owner,a.owner).status==='WAR');if(hostile.length){openBattle(army,hostile.sort((a,b)=>a.troops-b.troops)[0],tile,false);return}if(enemies.length){addLog(relationMessage(enemies[0].owner));state.movingArmyId=null;renderAll();return}const zocFort=isBlockedByEnemyFortZOC(state,tile,army.owner),previousOwner=tile.owner;army.q=tile.q;army.r=tile.r;army.ap=zocFort?0:army.ap-1;army.zocSupplyCut=zocFort;tile.owner=army.owner;if(zocFort){army.morale=Math.max(0,army.morale-15);army.supplied=false;tile[`suppliedFor${army.owner}`]=false;addLog(`⚠️ ${army.name}이 적 산성 ZOC를 강행 돌파했습니다. 사기 -15, AP 소진, 보급 단절!`)}else addLog(`${army.name}이 (${tile.q},${tile.r})로 이동했습니다.`);if(previousOwner!==army.owner)onTileCaptured(previousOwner,army.owner,tile,army);state.movingArmyId=null;state.selectedTileKey=tileKey(tile.q,tile.r);updateSupplyLines(state);if(zocFort){army.supplied=false;tile[`suppliedFor${army.owner}`]=false}renderAll()}

function advanceDiplomacyTurn(){for(const relation of Object.values(state.relations)){if(relation.status==='SECRET_PACT'&&relation.expiresAt!==null&&state.turn>=relation.expiresAt){relation.status='NEUTRAL';relation.expiresAt=null;relation.note='';addLog('은밀한 밀약 기간이 끝나 양국 관계가 다시 경계·대치로 돌아섰습니다.')}}}
function applyPeasantUnrest(){if(state.legitimacy>30||state.lastPeasantRevoltTurn===state.turn)return;state.lastPeasantRevoltTurn=state.turn;state.nationalGold=Math.max(0,state.nationalGold-50);state.nationalFood=Math.max(0,state.nationalFood-80);for(const army of playerArmies())army.morale=Math.max(0,army.morale-5);addLog('🔥 천명·민심이 30 이하로 무너져 민란이 일어났습니다. 국고 -50, 군량 -80, 전 군단 사기 -5.')}
function nextTurn(){if(!state.started)return;state.turn++;state.month++;if(state.month>12){state.month=1;state.year++}let foodGain=180,goldGain=90;for(const tile of Object.values(state.tiles))if(tile.owner===state.playerFaction&&tile.node){if(tile.node.type==='CAPITAL'){foodGain+=120;goldGain+=80}if(tile.node.type==='TOWN'){foodGain+=70;goldGain+=40}if(tile.node.type==='PORT')goldGain+=90}state.nationalFood+=foodGain;state.nationalGold+=goldGain;state.iron+=(Object.values(state.tiles).filter(t=>t.owner===state.playerFaction&&['ung-san-mines','ulsan','hapcheon'].includes(t.node?.id)).length)*12;state.horses+=(Object.values(state.tiles).filter(t=>t.owner===state.playerFaction&&t.node?.id==='chuncheon').length)*10;updateSupplyLines(state);const house=activeClan();if(house){house.gold+=(house.manorLevel||0)*60;house.privateArmy+=(house.manorLevel||0)*150;for(const c of playerClans())if(c.loyaltyDecayTurns>0){c.loyalty=Math.max(0,c.loyalty-5);c.loyaltyDecayTurns--}}for(const army of playerArmies()){army.ap=2;if(!army.supplied){const loss=Math.floor(army.troops*.22);army.troops=Math.max(200,army.troops-loss);army.morale=Math.max(20,army.morale-25);addLog(`${army.name} 보급 단절: 병력 ${loss}명 손실.`)}else{army.morale=Math.min(100,army.morale+10+(state.legitimacy>=70?5:0));if(army.troops<army.maxTroops&&state.nationalFood>=100){army.troops=Math.min(army.maxTroops,army.troops+200);state.nationalFood-=100}}}state.armies=state.armies.filter(a=>a.troops>50);for(const enemy of state.armies.filter(a=>a.owner!==state.playerFaction))enemy.ap=2;advanceDiplomacyTurn();applyPeasantUnrest();checkNobleRevoltRisk();runEnemyTurns(state,{log:addLog,queueBattle:(a,d,t,isAI)=>openBattle(a,d,t,isAI),onTileCaptured});updateSupplyLines(state);if(state.triggers.hanseongBattleTurn!==null&&state.turn>=state.triggers.hanseongBattleTurn){state.triggers.hanseongBattleTurn=null;if(!state.quests.completed.has('MQ-02'))if(state.playerFaction==='SILLA'||state.playerFaction==='BAEKJE')showCutscene(state.playerFaction==='BAEKJE'?'CS-02-B':'CS-02-S')}checkActionTriggers('turn');addLog(`${state.year}년 ${state.month}월 · 군량 +${foodGain}, 금 +${goldGain}.`);renderAll()}

function hexToPixel(q,r){return{x:HEX_SIZE*Math.sqrt(3)*(q+r/2)+110,y:HEX_SIZE*1.5*r+95}}
function drawHex(x,y,size,fill,stroke,width=2){ctx.beginPath();for(let i=0;i<6;i++){const angle=Math.PI/180*(60*i-30),vx=x+size*Math.cos(angle),vy=y+size*Math.sin(angle);i?ctx.lineTo(vx,vy):ctx.moveTo(vx,vy)}ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.lineWidth=width;ctx.strokeStyle=stroke;ctx.stroke()}
function renderCanvas(){const rect=canvas.parentElement.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);const cam=state.camera;ctx.setTransform(dpr*cam.zoom,0,0,dpr*cam.zoom,dpr*cam.x,dpr*cam.y);const moving=state.armies.find(a=>a.id===state.movingArmyId);for(const [key,tile]of Object.entries(state.tiles)){const{x,y}=hexToPixel(tile.q,tile.r),faction=FACTIONS[tile.owner],selected=key===state.selectedTileKey,target=moving&&getDistance(moving.q,moving.r,tile.q,tile.r)===1,targetAllowed=target&&(tile.owner===moving.owner||getRelation(state,moving.owner,tile.owner).status==='WAR')&&!state.armies.some(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==moving.owner&&getRelation(state,moving.owner,a.owner).status!=='WAR'),zocTarget=targetAllowed&&Boolean(isBlockedByEnemyFortZOC(state,tile,moving.owner));drawHex(x,y,HEX_SIZE-2,`${faction.color}44`,target?(targetAllowed?(zocTarget?'#f97316':'#3fb950'):'#6b7280'):selected?'#fff':faction.border,target||selected?4:2);if(target&&!targetAllowed){ctx.fillStyle='#9ca3af';ctx.font='bold 24px sans-serif';ctx.fillText('×',x,y+8)}if(zocTarget){ctx.fillStyle='#fb923c';ctx.font='bold 10px sans-serif';ctx.fillText('⚠️ 산성위협',x,y+41)}if(tile.owner===state.playerFaction&&!tile[`suppliedFor${state.playerFaction}`])drawHex(x,y,HEX_SIZE-8,'#f8514925','#f85149',1);ctx.textAlign='center';ctx.fillStyle='#8b949e';ctx.font='11px sans-serif';ctx.fillText(`(${tile.q},${tile.r}) ${tile.terrain}`,x,y-25);if(tile.node){const icon=tile.node.type==='FORT'?'▣':tile.node.type==='CAPITAL'?'♛':tile.node.type==='PORT'?'⚓':'◆';ctx.fillStyle='#fff';ctx.font='bold 12px sans-serif';ctx.fillText(`${icon} ${tile.node.name}`,x,y-7)}const stack=state.armies.filter(a=>a.q===tile.q&&a.r===tile.r);if(stack.length){const total=stack.reduce((sum,a)=>sum+a.troops,0),supplied=stack.every(a=>a.supplied),owners=new Set(stack.map(a=>a.owner));ctx.fillStyle=owners.size>1?'#6b21a8':FACTIONS[stack[0].owner].color;ctx.fillRect(x-43,y+2,86,27);ctx.strokeStyle=supplied?'#93c5fd':'#f85149';ctx.lineWidth=2;ctx.strokeRect(x-43,y+2,86,27);ctx.fillStyle='#fff';ctx.font='bold 11px sans-serif';ctx.fillText(`⚔ ${total.toLocaleString()}명${stack.length>1?` (×${stack.length})`:''}`,x,y+14);ctx.font='10px sans-serif';ctx.fillStyle=supplied?'#86efac':'#fca5a5';ctx.fillText(supplied?'보급 정상':'보급 단절',x,y+26)}}}

function questObjective(id){const key=({ 'MQ-01':'objectiveMq01','MQ-02':'objectiveMq02','MQ-03':'objectiveMq03','MQ-04':'objectiveMq04','MQ-G1':'objectiveG1','MQ-G2':'objectiveG2','MQ-G3':'objectiveG3','MQ-G4':'objectiveG4'})[id];return UI_LABELS[key]||''}function renderQuestCards(quests){let futureShown=false;return quests.map((quest,index)=>{const completed=state.quests.completed.has(quest.id),active=index===state.quests.mainIndex;if(!completed&&!active){if(futureShown)return'';futureShown=true;return`<div class="quest-card quest-blind"><b>${UI_LABELS.questUnknown}</b><p>${UI_LABELS.questUnknownDescription}</p></div>`}const history=(state.quests.history||[]).filter(entry=>entry.questId===quest.id);const record=history.map(entry=>`<div class="quest-chronicle">${UI_LABELS.questChroniclePrefix} &middot; Turn ${entry.turn}: ${escapeHtml(entry.choice)} &rarr; ${escapeHtml(entry.result)}</div>`).join('');return`<div class="quest-card ${active?'active':''}"><b>${quest.id} &middot; ${escapeHtml(quest.title)}</b><span class="quest-state">${completed?UI_LABELS.questDone:UI_LABELS.questActive}</span><p>${escapeHtml(quest.description)}</p>${active?`<p class="quest-objective">${questObjective(quest.id)}</p>`:''}${record}</div>`}).join('')}
function renderTileSelection(){const tile=state.tiles[state.selectedTileKey],card=$('tile-card'),info=$('tile-info'),actions=$('tile-actions');card.hidden=!state.tileCardOpen;actions.replaceChildren();if(!tile||!state.tileCardOpen){info.textContent='\uD0C0\uC77C\uC744 \uC120\uD0DD\uD558\uC138\uC694.';return}const all=state.armies.filter(a=>a.q===tile.q&&a.r===tile.r),own=all.filter(a=>a.owner===state.playerFaction);if(!own.some(a=>a.id===state.selectedArmyId))state.selectedArmyId=own[0]?.id||null;const selected=own.find(a=>a.id===state.selectedArmyId),supply=tile[`suppliedFor${state.playerFaction}`];info.innerHTML=`<div class="tile-summary"><b>\uC88C\uD45C</b> (${tile.q}, ${tile.r}) · <b>\uC18C\uC720</b> ${escapeHtml(FACTIONS[tile.owner]?.name||tile.owner)} · <b>\uBCF4\uAE09</b> ${supply?'\uC5F0\uACB0':'\uB2E8\uC808'}</div><div class="army-list">${all.length?all.map(a=>`<button class="army-row ${a.id===state.selectedArmyId?'selected':''}" data-army-row="${escapeHtml(a.id)}"><b>${escapeHtml(a.name)}</b><span>${escapeHtml(FACTIONS[a.owner]?.name||a.owner)} · ${a.troops.toLocaleString()}\uBA85</span><small>\uC0AC\uAE30 ${a.morale}% · AP ${a.ap}</small></button>`).join(''):'<p class="empty-armies">\uC8FC\uB454 \uAD70\uB2E8 \uC5C6\uC74C</p>'}</div>`;info.querySelectorAll('[data-army-row]').forEach(row=>row.onclick=()=>{state.selectedArmyId=row.dataset.armyRow;renderAll()});if(selected){const picker=document.createElement('label');picker.className='commander-picker';picker.textContent='지휘 장수 ';const select=document.createElement('select');select.innerHTML=state.generals.filter(g=>g.faction===state.playerFaction).map(g=>`<option value="${g.id}" ${g.id===selected.commanderId?'selected':''}>${escapeHtml(g.name)} · 통솔 ${g.leadership}/무력 ${g.martial}</option>`).join('');select.onchange=()=>{selected.commanderId=select.value;renderAll()};picker.append(select);info.append(picker)}const add=(label,disabled,handler,tooltip='')=>{const b=document.createElement('button');b.textContent=label;b.disabled=disabled;if(tooltip)b.dataset.tooltip=tooltip;b.onclick=handler;actions.append(b)};add(state.movingArmyId===selected?.id?'↩ \uC774\uB3D9 \uCDE8\uC18C':'⚔️ \uC120\uD0DD \uAD70\uB2E8 \uC774\uB3D9/\uACF5\uACA9',!selected,()=>{if(state.movingArmyId===selected.id){state.movingArmyId=null;renderAll()}else startMoveArmy(selected.id)});add('➗ \uC808\uBC18 \uBD84\uD560',!selected||selected.troops<1000,()=>splitArmyById(selected.id),UI_LABELS.tooltipSplit);add('🔗 \uD0C0\uC77C \uB0B4 \uAD70\uB2E8 \uBCD1\uD569',own.length<2,()=>mergeArmiesOnTile(tile.q,tile.r));add('➕ \uC2E0\uADDC \uCC3D\uC124',tile.owner!==state.playerFaction||!tile.node,()=>chooseArmyType(tile.q,tile.r))}
function renderUIv04(){
  $('ui-turn').textContent=`${state.year}년 ${state.month}월 · Turn ${state.turn}`;$('ui-auth').textContent=`${state.royalAuth}%`;$('ui-food').textContent=state.nationalFood.toLocaleString();$('ui-gold').textContent=state.nationalGold.toLocaleString();$('ui-iron').textContent=state.iron.toLocaleString();$('ui-horses').textContent=state.horses.toLocaleString();$('ui-trust').textContent=`${state.trust}/100`;$('ui-legitimacy').textContent=`${state.legitimacy}/100`;$('ui-war-law').textContent='전쟁 명분 '+state.warJustification+'/100 · '+(state.northWarApproved?'출병 가능':'회의 승인 필요');$('ui-war-law').style.color=state.northWarApproved?'#3fb950':'#f85149';$('ui-faction-badge').textContent=state.started?`${FACTIONS[state.playerFaction].name} · ${FACTION_CAMPAIGNS[state.playerFaction].leader}`:'세력 선택 대기';
  $('council-title').textContent=councilName();const clan=activeClan();$('ui-role-badge').textContent=clan?.isKing?'왕실 지휘':'귀족 가문 지휘';$('ui-role-badge').className=`badge ${clan?.isKing?'badge-king':''}`;$('clan-role-badge').textContent=clan?.isKing?'왕실':'대귀족';$('clan-status').innerHTML=`<b>가문 수장:</b> ${clan?.leader} (${clan?.rank}) · <b>봉토:</b> ${clan?.fief}<br><b>가문 자금:</b> ${clan?.gold}금 · <b>사병:</b> ${clan?.privateArmy.toLocaleString()}명`;
  const quests=mainQuests();const mainQuest=quests[state.quests.mainIndex]||null;$('quest-progress').innerHTML=renderQuestCards(quests);$('narrative-flags').innerHTML=`<div class="flag-list">${FLAG_LABELS.map(([label,key])=>`<span>${label}</span><b>${state.flags[key]===true?'TRUE':state.flags[key]===false?'FALSE':state.flags[key]??'미설정'}</b>`).join('')}<span>TRUST_baekje_silla</span><b>${state.trust}</b><span>천명/민심</span><b>${state.legitimacy}</b><span>REL_isabu</span><b>${state.isabuRelation}</b></div>`;$('diplomacy-status').innerHTML=`백제-신라 신뢰 <b>${state.trust}/100</b><br>동맹 상태 <b>${state.allianceBroken?'파기 · 백제 복수 총공세':'유지 · 한성 공동 북진'}</b><br>고구려 밀약 <b>${state.flags.goguryeoPact?'성립':'미발견'}</b>`;$('people-status').innerHTML=state.playerFaction==='SILLA'?`6두품 문관 등용(SQ-01): ${escapeHtml(state.quests.sq01Survives||'미발생')}<br>화랑도 인재 육성(SQ-05): ${escapeHtml(state.quests.sq05Survives||'미발생')}`:state.playerFaction==='BAEKJE'?`22담로 파견 왕족(SQ-02): ${state.quests.sideCompleted.has('SQ-02')?'완료':'미발생'}<br>대가야 철기 교역망(SQ-03): ${state.quests.sideCompleted.has('SQ-03')?'완료':'미발생'}`:`태학의 그림자·북방 방어(SQ-04): ${state.quests.sideCompleted.has('SQ-04')?'완료':'미발생'}<br>온달/평원왕계 신진 무관 발탁: ${state.quests.mainIndex>0?'진행 중':'대기'}`;
  renderTileSelection();
  const tbody=$('council-tbody');tbody.replaceChildren();for(const c of playerClans()){const tr=document.createElement('tr'),agree=c.isKing||c.loyalty>=55;tr.dataset.metric='clan:'+c.id;tr.innerHTML=`<td><b>${c.name}</b><br><span>${c.leader}</span></td><td>${c.rank}</td><td>${c.privateArmy.toLocaleString()}</td><td>${c.isKing?'왕실':`${c.loyalty}%`}</td><td style="color:${agree?'#3fb950':'#f85149'}">${agree?'찬성':'반대'}</td>`;tbody.append(tr)}$('council-tab-label').textContent=`🏛️ 조정·${councilName()}`;$('btn-agenda-war').textContent=state.playerFaction==='SILLA'?'북진 총공세 의제 상정':state.playerFaction==='BAEKJE'?'한성 고토수복 의제 상정':'남방 방어·한강 사수령';$('btn-centralize').textContent=state.playerFaction==='SILLA'?'율령 반포·골품 정비':state.playerFaction==='BAEKJE'?'22담로 왕족 파견·8대성 견제':'5부 귀족 통제·태학 정비';$('btn-agenda-war').disabled=!clan?.isKing||state.northWarApproved;$('btn-centralize').disabled=!clan?.isKing&&state.playerFaction==='SILLA';$('btn-reject-order').hidden=clan?.isKing;$('btn-reject-order').disabled=clan?.isKing;$('btn-accept-order').hidden=clan?.isKing;$('btn-accept-order').disabled=clan?.isKing;
}
function renderNarrativeDetails(){const labels={treatyClarity:'한강 맹약 문서화',sillaRaidScope:'나제동맹 기습 수위',baekjeResponse:'백제의 대응',gwansanOutcome:'관산성 결전의 결말',goguryeoPact:'고구려 밀약 첩보',gayaFavorBaekje:'대가야 외교 태도 · 백제 호감',gayaFavorSilla:'대가야 외교 태도 · 신라 호감'},values={HIGH:'명확히 규정됨',LOW:'모호하게 기록됨',NONE:'문서화되지 않음',FULL:'전부 취함',PARTIAL:'일부 취함',PREEMPT:'선제 대응',IGNORE:'동맹을 신뢰',true:'있음',false:'없음',null:'아직 발생 전'};const rows=Object.entries(labels).map(([key,label])=>`<span>${label}</span><b>${values[state.flags[key]]??state.flags[key]??'아직 발생 전'}</b>`);rows.push(`<span data-metric="trust" tabindex="0">나제동맹 신뢰도</span><b data-metric="trust" tabindex="0">${state.trust}</b>`,`<span data-metric="mandate" tabindex="0">천명·민심</span><b data-metric="mandate" tabindex="0">${state.legitimacy}</b>`);if(state.playerFaction==='SILLA')rows.push(`<span>장군 이사부 신임도</span><b>${state.isabuRelation}</b>`);if(state.playerFaction==='BAEKJE')rows.push(`<span>성왕·왕자 여창 갈등 지수</span><b>${Math.max(0,100-state.legitimacy)}</b>`);if(state.playerFaction==='GOGURYEO')rows.push(`<span>5부 귀족 결속도</span><b>${Math.round(playerClans().filter(c=>!c.isKing).reduce((n,c)=>n+c.loyalty,0)/Math.max(1,playerClans().filter(c=>!c.isKing).length))}</b>`);$('narrative-flags').innerHTML=`<div class="flag-list">${rows.join('')}<details><summary>🛠️ 개발자 플래그 보기</summary><div class="flag-list">${Object.entries(state.flags).map(([key,value])=>`<span>${key}</span><b>${String(value??'null')}</b>`).join('')}</div></details></div>`}
function renderWorldActions(){const box=$('world-actions');if(!box)return;$('diplomacy-status').innerHTML=`<b>전쟁 명분</b> ${state.warJustification}/100 · <b>한강 전운</b> ${state.worldTension}/100<br>${state.lastWorldBriefing}<br><br>백제-신라 신뢰 ${state.trust}/100 · ${state.allianceBroken?'동맹 파기':'동맹 유지'}`;box.replaceChildren();const spy=document.createElement('button');spy.textContent='🕵️ 국경 유언비어·고토 회복 공작 (국고 80 → 명분 +25)';spy.disabled=state.nationalGold<80;spy.onclick=()=>{state.nationalGold-=80;state.warJustification=Math.min(100,state.warJustification+25);state.worldTension=Math.min(100,state.worldTension+5);state.lastWorldBriefing='국경의 민심이 옛 강역 회복을 요구한다는 소문이 퍼졌습니다.';addLog('국경 공작으로 전쟁 명분이 25 상승했습니다.');renderAll()};const monument=document.createElement('button');monument.textContent='📜 옛 강역 문서·비석 선포 (민심 -8 → 명분 +20)';monument.disabled=state.legitimacy<8;monument.onclick=()=>{state.legitimacy-=8;state.warJustification=Math.min(100,state.warJustification+20);state.lastWorldBriefing='왕실이 옛 강역의 문서와 비석을 조정에 공개했습니다.';addLog('옛 강역 선포로 전쟁 명분이 20 상승했습니다.');renderAll()};box.append(spy,monument);const agenda=$('btn-agenda-war');if(agenda){const clan=activeClan();agenda.disabled=!clan?.isKing||state.northWarApproved||state.warJustification<60;agenda.title=state.warJustification<60?`⚠️ 전쟁 명분 부족 (현재 ${state.warJustification}/60) - 정세 공작이나 국경 마찰이 필요합니다`:''}}
function houseHome(){const start=factionStarts[state.playerFaction];return state.tiles[start?.tile]||Object.values(state.tiles).find(t=>t.owner===state.playerFaction)}
function spawnHouseArmy(clan,troops,name){const home=houseHome();if(!home)return null;state.armySeq++;const army={id:`house_${state.playerFaction.toLowerCase()}_${state.armySeq}`,name:name||`${clan.leader} 본가 정예군`,owner:state.playerFaction,clanId:clan.id,q:home.q,r:home.r,troops,maxTroops:Math.max(1000,troops),morale:100,supplied:true,ap:2};state.armies.push(army);return army}
function houseAction(action){const clan=activeClan();if(!clan)return;if(action==='sortie'){if(clan.privateArmy<800)return addLog('본가 사병 800명이 있어야 출진할 수 있습니다.');clan.privateArmy-=800;const army=spawnHouseArmy(clan,800);if(!army)return;addLog(`본가 정예군 ${army.name}이 수도에 출진했습니다.`)}if(action==='manor'){if(clan.gold<150)return addLog('장원 증축에는 가문 자금 150금이 필요합니다.');clan.gold-=150;clan.manorLevel++;state.royalAuth=Math.min(100,state.royalAuth+5);addLog(`장원을 ${clan.manorLevel}단계로 증축했습니다. 매 턴 가문 자금과 사병이 늘고 왕권이 5 상승합니다.`)}if(action==='spy'){if(clan.gold<100)return addLog('밀정 파견에는 가문 자금 100금이 필요합니다.');clan.gold-=100;clan.leverage++;addLog(`Spies obtained one piece of leverage. Total leverage: ${clan.leverage}.`)}if(action==='hunt'){if(clan.gold<120)return addLog('수렵 대회에는 가문 자금 120금이 필요합니다.');clan.gold-=120;for(const c of playerClans())c.loyalty=Math.min(100,c.loyalty+10);state.legitimacy=Math.min(100,state.legitimacy+8);if(Math.random()<.35){state.commanderBonusByFaction??={};state.commanderBonusByFaction[state.playerFaction]=(state.commanderBonusByFaction[state.playerFaction]||1)+.05;addLog('신진 무관이 발탁되었습니다. 아군 전투력이 영구히 5% 상승합니다.')}else addLog('수렵 대회와 연회로 모든 가문 충성도 +10, 천명·민심 +8.')}renderAll()}function nobleAction(action,id){const house=activeClan(),target=state.clans[id];if(!house||!target||target===house)return;const martial=['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu'].includes(id),conservative=['park_noble','baekje_sa','goguryeo_go'].includes(id),cautious=['silla_seok','silla_lee','baekje_mok','goguryeo_ondal'].includes(id);if(action==='bribe'){if(house.gold<100)return addLog('밀정 파견에는 가문 자금 100금이 필요합니다.');house.gold-=100;let gain=cautious?8:15;if(conservative)gain=Math.round(gain*1.5);if(martial)gain=Math.round(gain*.75);target.loyalty=Math.min(100,target.loyalty+gain);addLog(`${target.name} accepted 100 gold. Loyalty +${gain}.`)}else if(action==='land'){if(state.promisedLandClanId&&state.promisedLandClanId!==id)return addLog('A fief is already promised to another house.');state.promisedLandClanId=id;target.loyalty=Math.min(100,target.loyalty+25);const army=spawnHouseArmy(target,1000,`${target.name} \uBD84\uBD09 \uC120\uBD09\uB300`);if(army)addLog(`${target.name} accepted a fief promise: loyalty +25 and 1,000 troops appeared at the capital.`)}else if(action==='marry'){if(state.marriageContracts.has(id))return addLog('This house already has a marriage or office contract.');state.marriageContracts.add(id);state.politicalAllies.add(id);target.loyalty=Math.min(100,target.loyalty+30);target.influence=(target.influence||0)+25;state.royalAuth=Math.max(0,state.royalAuth-8);addLog(`${target.name} entered a marriage and office alliance: loyalty +30, royal authority -8.`)}else if(action==='threaten'){if(house.leverage<1)return addLog('Send spies first to obtain leverage.');house.leverage--;target.loyalty=Math.max(55,target.loyalty);target.threatened=true;target.loyaltyDecayTurns=3;state.royalAuth=Math.min(100,state.royalAuth+5);addLog(`${target.name} was forced to vote yes. Royal authority +5; loyalty will decline for three turns.`)}else if(action==='purge'){target.purgesCount++;const chance=Math.max(.2,.65-.15*(target.purgesCount-1));if(Math.random()<chance){const gold=Math.floor(target.gold/2),troops=Math.floor(target.privateArmy/2);target.gold-=gold;target.privateArmy-=troops;target.loyalty=Math.max(0,target.loyalty-20);state.nationalGold+=gold;state.royalAuth=Math.min(100,state.royalAuth+15);addLog(`숙청 성공: ${target.name}의 금 ${gold}과 사병 ${troops}명을 몰수했습니다. 왕권 +15.`)}else{target.loyalty=Math.max(0,target.loyalty-50);const home=Object.values(state.tiles).find(t=>t.owner===state.playerFaction&&t.node);if(home){FACTIONS.REBELS??={name:'반란군',color:'#f85149',border:'#ff7b72'};const troops=Math.max(500,Math.floor(target.privateArmy/2));state.armySeq++;state.armies.push({id:`rebel_${state.turn}_${state.armySeq}`,name:`${target.name} rebels`,owner:'REBELS',clanId:id,q:home.q,r:home.r,troops,maxTroops:troops,morale:95,supplied:false,ap:2});setRelation(state,state.playerFaction,'REBELS','WAR');addLog(`숙청 실패: ${target.name}이 본거지에서 반란군 ${troops}명을 일으켰습니다.`)}}}renderAll()}function renderClanContracts(){const box=$('clan-actions'),list=$('noble-list'),houseBox=$('house-actions');if(!box||!list||!houseBox)return;box.replaceChildren();list.replaceChildren();houseBox.replaceChildren();const clan=activeClan();if(!clan)return;for(const [action,label,disabled] of [['sortie','Army sortie: 800 private troops -> create direct army',clan.privateArmy<800],['manor','Expand manor: 150 house gold',clan.gold<150],['spy','Send spies: 100 house gold',clan.gold<100],['hunt','Royal hunt and feast: 120 house gold',clan.gold<120]]){const button=document.createElement('button');button.textContent=$('house-label-'+action)?.textContent||label;button.disabled=disabled;button.dataset.tooltip=UI_LABELS['tooltip'+action[0].toUpperCase()+action.slice(1)]||'';button.onclick=()=>houseAction(action);houseBox.append(button)}const status=document.createElement('p');status.className='house-economy';status.textContent=$('house-economy-label').textContent.replace('{level}',clan.manorLevel).replace('{gold}',60*clan.manorLevel).replace('{troops}',150*clan.manorLevel).replace('{leverage}',clan.leverage);houseBox.prepend(status);for(const target of playerClans().filter(c=>c.id!==clan.id)){const card=document.createElement('button');card.className=`noble-card ${state.selectedNobleId===target.id?'active':''}`;card.dataset.metric=`clan:${target.id}`;card.innerHTML=`<b>${target.name}</b><small>${$('noble-meta-label').textContent.replace('{loyalty}',target.loyalty).replace('{troops}',target.privateArmy.toLocaleString())}</small>`;card.onclick=()=>{state.selectedNobleId=target.id;renderClanContracts()};list.append(card)}const target=state.clans[state.selectedNobleId]||playerClans().find(c=>c.id!==clan.id);if(target&&target!==clan){state.selectedNobleId=target.id;box.className='clan-actions-grid';const options=[['bribe','Bribe: 100 house gold | Result: loyalty increases'],['land','Promise a fief | Result: +25 loyalty, 1,000 allied troops appear now'],['marry','Marriage or office | Result: +30 loyalty, royal authority -8'],['threaten','Threaten with leverage | Result: force a yes vote, authority +5'],['purge','Purge the house | Result: success takes half assets; failure spawns rebels']];for(const[action,label]of options){const button=document.createElement('button');button.textContent=`${target.name}: ${$('noble-label-'+action)?.textContent||label}`;button.disabled=(action==='bribe'&&clan.gold<100)||(action==='land'&&Boolean(state.promisedLandClanId&&state.promisedLandClanId!==target.id))||(action==='marry'&&state.marriageContracts.has(target.id))||(action==='threaten'&&clan.leverage<1);button.dataset.tooltip=UI_LABELS['tooltip'+action[0].toUpperCase()+action.slice(1)]||'';button.onclick=()=>nobleAction(action,target.id);box.append(button)}}}function showPromisedLandSettlement(tile){const clan=state.clans[state.promisedLandClanId];if(!clan){state.promisedLandClanId=null;state.promisedSettlementPending=false;return}let dialog=document.getElementById('land-promise-settlement');if(!dialog){dialog=document.createElement('dialog');dialog.id='land-promise-settlement';document.body.append(dialog)}dialog.innerHTML=`<h2>분봉 약속의 정산</h2><p>${tile.node?.name||`좌표 (${tile.q}, ${tile.r})`}을(를) ${clan.name}에 약속했습니다. 맹약을 지키겠습니까?</p><div class="btn-row"><button id="promise-honor">🅰️ 약속대로 봉토로 내어준다</button><button id="promise-break" class="btn-danger">🅱️ 왕실 직할령으로 삼고 약속을 파기한다</button></div>`;dialog.querySelector('#promise-honor').onclick=()=>{clan.fief=tile.node?.name||`(${tile.q},${tile.r})`;clan.loyalty=Math.min(100,clan.loyalty+20);clan.privateArmy+=500;state.clanTaxShare=Math.min(.5,state.clanTaxShare+.08);state.promisedLandClanId=null;state.promisedSettlementPending=false;dialog.close();addLog(`${clan.name}에 ${clan.fief}을 분봉했습니다. 충성 +20, 사병 +500, 세수 일부를 넘깁니다.`);renderAll()};dialog.querySelector('#promise-break').onclick=()=>{state.royalAuth=Math.min(100,state.royalAuth+10);clan.loyalty=Math.max(0,clan.loyalty-50);state.promisedLandClanId=null;state.promisedSettlementPending=false;dialog.close();addLog(`${clan.name}과의 분봉 약속을 파기했습니다. 왕권 +10, 충성 -50.`);if(Math.random()<.5){const rebelOwner=['SILLA','BAEKJE','GOGURYEO'].find(f=>f!==state.playerFaction),troops=Math.min(900,clan.privateArmy);clan.privateArmy=Math.max(0,clan.privateArmy-troops);state.armies.push({id:`rebellion_${state.turn}_${tile.q}_${tile.r}`,name:`${clan.name} 반란군`,owner:rebelOwner,clanId:clan.id,q:tile.q,r:tile.r,troops,maxTroops:troops,morale:90,supplied:false,ap:2});tile.owner=rebelOwner;addLog(`⚔️ ${clan.name}이 사병 ${troops}명으로 반란을 일으켰습니다!`)}renderAll()};dialog.showModal()}
function checkNationCollapse(){for(const faction of ['SILLA','BAEKJE','GOGURYEO']){if(state.annexedNations.has(faction)||Object.values(state.tiles).some(tile=>tile.owner===faction))continue;state.annexedNations.add(faction);const captor=state.collapseCaptors[faction]||state.playerFaction;state.armies=state.armies.filter(army=>army.owner!==faction);if(captor===state.playerFaction){state.nationalGold+=400;state.nationalFood+=500;state.legitimacy=Math.min(100,state.legitimacy+15);state.royalAuth=Math.min(100,state.royalAuth+10)}const boss=['BAEKJE','GOGURYEO','SILLA'].find(id=>id!==faction&&id!==state.playerFaction&&!state.annexedNations.has(id)&&Object.values(state.tiles).some(tile=>tile.owner===id));if(boss){const hubs=Object.values(state.tiles).filter(tile=>tile.owner===boss&&tile.node).sort((a,b)=>(a.node.type==='CAPITAL'?-1:0)-(b.node.type==='CAPITAL'?-1:0));const home=hubs[0]||Object.values(state.tiles).find(tile=>tile.owner===boss);if(home){setRelation(state,state.playerFaction,boss,'WAR');for(let i=0;i<2;i++){state.aiArmySeq=(state.aiArmySeq||0)+1;state.armies.push({id:'annex_muster_'+boss+'_'+state.turn+'_'+i,name:FACTIONS[boss].name+' 비상 총동원군',owner:boss,clanId:null,q:home.q,r:home.r,troops:4000,maxTroops:4000,morale:100,supplied:true,ap:2})}}}state.collapseCaptors[faction]=captor;addLog('🔥 '+FACTIONS[faction].name+' 국가 패망! 잔존 적국이 비상 총동원령을 선포했습니다.');state.eventQueue.unshift({type:'annex',id:faction})}}
function renderAnnexationEvent(faction){const boss=['BAEKJE','GOGURYEO','SILLA'].find(id=>id!==faction&&id!==state.playerFaction&&Object.values(state.tiles).some(tile=>tile.owner===id));$('cutscene-kicker').textContent='삼한 패권 결전';$('cutscene-title').textContent='🔥 '+FACTIONS[faction].name+' 패망 대사건';$('cutscene-context').hidden=false;$('cutscene-context').textContent='마지막 거점이 함락되며 '+FACTIONS[faction].name+'의 조정이 무너졌습니다. 유민과 귀족이 항복하고 잔존 적국'+(boss?' '+FACTIONS[boss].name:'')+'이(가) 비상 총동원령을 내렸습니다.'+(state.collapseCaptors[faction]===state.playerFaction?' 정복 보상: 국고 +400금, 군량 +500, 천명 +15, 왕권 +10.':'')+' 최종 전선을 향해 정예군이 집결합니다.';const line=$('cutscene-lines');line.replaceChildren();$('cutscene-choices').replaceChildren();$('cutscene-choices').hidden=false;$('cutscene-context').hidden=false;$('cutscene-page-indicator').hidden=true;$('btn-cutscene-continue').style.display='none';$('btn-cutscene-skip').style.display='none';$('btn-cutscene-close').style.display='inline-block';$('btn-cutscene-close').textContent='확인';$('btn-cutscene-close').onclick=()=>{$('cutscene-modal').close();state.eventOpen=false;renderAll();queueMicrotask(pumpStoryQueue)};$('cutscene-modal').showModal()}
