canvas.addEventListener('click',event=>{if(!state.started)return;if(state.suppressMapClick){state.suppressMapClick=false;return}const rect=canvas.getBoundingClientRect(),mx=(event.clientX-rect.left-state.camera.x)/state.camera.zoom,my=(event.clientY-rect.top-state.camera.y)/state.camera.zoom;let clicked=null,best=Infinity;for(const tile of Object.values(state.tiles)){const{x,y}=hexToPixel(tile.q,tile.r),distance=Math.hypot(mx-x,my-y);if(distance<HEX_SIZE*.85&&distance<best){best=distance;clicked=tile}}if(!clicked)return;if(state.movingArmyId)tryMoveOrAttack(clicked);else{state.selectedTileKey=tileKey(clicked.q,clicked.r);state.selectedArmyId=state.armies.find(a=>a.owner===state.playerFaction&&a.q===clicked.q&&a.r===clicked.r)?.id||null;state.tileCardOpen=true;if(state.playerFaction==='BAEKJE'&&clicked.owner===state.playerFaction&&!clicked.node)markStateAction('baekje-rear');renderAll()}});
